<template>
  <DwDialog
    :model-value="modelValue"
    :title="`Share “${dashboard?.name || ''}”`"
    subtitle="Recipients get access through 3DEXPERIENCE and find it under Saved dashboards › Shared with me."
    icon="mdi-share-variant-outline"
    :busy="busy"
    max-width="600"
    @update:model-value="$emit('update:modelValue', $event)"
  >
    <div class="dw-field">
      <label class="dw-label" for="share-people">Add people</label>
      <div class="share-add">
        <v-autocomplete
          id="share-people"
          v-model="selected"
          v-model:search="query"
          :items="results"
          :loading="searching"
          item-title="name"
          item-value="id"
          return-object
          multiple
          chips
          closable-chips
          hide-no-data
          no-filter
          placeholder="Search by name or username"
          hide-details="auto"
          :error-messages="addError"
          :disabled="busy || !canManage"
          class="share-add__input"
        >
          <template #item="{ props, item }">
            <v-list-item v-bind="props" :subtitle="rawOf(item).login" :disabled="isGranted(rawOf(item))">
              <template v-if="isGranted(rawOf(item))" #append><span class="dw-caption">Already has access</span></template>
            </v-list-item>
          </template>
        </v-autocomplete>
        <v-select v-model="level" :items="levels" item-title="label" item-value="value" hide-details class="share-add__level" :disabled="busy || !canManage" aria-label="Access level" />
      </div>
    </div>

    <div v-if="!checkingRights && !canManage" class="dw-alert" role="status">
      <v-icon icon="mdi-information-outline" size="18" /><span>You can see who has access, but you don't have permission to change sharing for this dashboard.</span>
    </div>

    <div class="dw-field">
      <div class="share-list-head">
        <span class="dw-label">People with access</span>
        <span class="dw-count">{{ grantees.length + 1 }}</span>
      </div>
      <div class="share-list" :aria-busy="loadingGrantees ? 'true' : 'false'">
        <div class="share-row">
          <span class="share-avatar">{{ initials(ownerLabel) }}</span>
          <div class="share-row__text"><div class="share-row__name">{{ ownerLabel }}</div></div>
          <span class="dw-badge dw-badge--primary">Owner</span>
        </div>
        <div v-if="loadingGrantees" class="share-row"><span class="dw-spinner" aria-hidden="true" /> <span class="dw-caption">Loading current access…</span></div>
        <div v-for="g in grantees" :key="g.id" class="share-row">
          <span class="share-avatar">{{ initials(g.name || g.login) }}</span>
          <div class="share-row__text">
            <div class="share-row__name">{{ g.name || g.login }}</div>
            <div v-if="g.login" class="dw-caption">{{ g.login }}</div>
          </div>
          <span v-if="g.inherited || !canManage" class="dw-badge" :title="g.inherited ? 'Inherited access can\'t be changed here' : ''">
            {{ levelLabel(g.level) }}<template v-if="g.inherited"> · inherited</template>
          </span>
          <template v-else>
            <v-select
              :model-value="g.level"
              :items="levelsFor(g)"
              item-title="label"
              item-value="value"
              density="compact"
              hide-details
              class="share-row__level"
              :aria-label="`Access level for ${g.name || g.login}`"
              :disabled="busy"
              @update:model-value="(v) => changeLevel(g, v)"
            />
            <button type="button" class="icon-btn" :aria-label="`Remove access for ${g.name || g.login}`" :disabled="busy" @click="revoke(g)">
              <v-icon icon="mdi-account-remove-outline" />
            </button>
          </template>
        </div>
      </div>
    </div>

    <div v-if="error" class="dw-alert dw-alert--error" role="alert">
      <v-icon icon="mdi-alert-circle-outline" size="18" /><span>{{ error }}</span>
    </div>

    <template #footer>
      <span class="dw-caption share-foot-note"><v-icon icon="mdi-shield-check-outline" size="16" /> Access is applied by 3DEXPERIENCE. Can Edit and Can Manage allow saving changes.</span>
      <button type="button" class="btn-outline" :disabled="busy" @click="$emit('update:modelValue', false)">Close</button>
      <button type="button" class="btn-primary" :class="{ 'btn-busy': busy }" :disabled="busy || !canManage || !selected.length" @click="share">
        <span v-if="busy" class="dw-spinner" aria-hidden="true" />
        {{ busy ? "Sharing…" : "Share" }}
      </button>
    </template>
  </DwDialog>
</template>

<script>
import DwDialog from "@/components/common/DwDialog.vue";
import sharingApi from "@/services/sharingApi";
import peopleApi from "@/services/peopleApi";
import { SHARING } from "@/config/platformConfig";
import { userMessage } from "@/services/apiError";
import { toastBus } from "@/components/common/toastBus";
import { ERROR_TEXT } from "@/utils/uiText";
import { useDashboardStore } from "@/store/dashboardStore";

// Share dialog (FR-11..FR-14). Success is reported only after the platform confirms.
export default {
  name: "ShareDialog",
  components: { DwDialog },
  props: {
    modelValue: Boolean,
    dashboard: { type: Object, default: null }, // { id, name, owner, ownerName }
  },
  emits: ["update:modelValue", "changed"],
  data() {
    return {
      levels: SHARING.levels,
      level: SHARING.defaultLevel,
      canManage: false,
      checkingRights: false,
      query: "",
      results: [],
      selected: [],
      searching: false,
      grantees: [],
      loadingGrantees: false,
      busy: false,
      error: "",
      addError: "",
      searchTimer: null,
      searchSeq: 0,
    };
  },
  computed: {
    ownerLabel() {
      return this.dashboard?.ownerName || this.dashboard?.owner || "Owner";
    },
  },
  watch: {
    modelValue(open) {
      if (open) this.reset();
    },
    query(text) {
      clearTimeout(this.searchTimer);
      this.searchTimer = setTimeout(() => this.search(text), 300);
    },
  },
  beforeUnmount() {
    clearTimeout(this.searchTimer);
  },
  methods: {
    initials(s) {
      return String(s || "?").split(/[\s.]+/).map((p) => p[0]).slice(0, 2).join("").toUpperCase();
    },
    // Vuetify passes either a wrapped list item ({ raw }) or the object itself.
    rawOf(item) {
      return item?.raw ?? item ?? {};
    },
    levelLabel(v) {
      return (this.levels.find((l) => l.value === v) || SHARING.levels.find((l) => l.value === v))?.label || v;
    },
    // A grantee may hold a level that isn't offered for new shares; keep it selectable.
    levelsFor(g) {
      return this.levels.some((l) => l.value === g.level) ? this.levels : [...this.levels, { value: g.level, label: this.levelLabel(g.level) }];
    },
    isGranted(p) {
      const key = (x) => String(x || "").toLowerCase();
      const me = useDashboardStore().user?.login;
      return (
        key(p.login) === key(this.dashboard?.owner) ||
        (!!me && key(p.login) === key(me)) ||
        this.grantees.some((g) => (p.personId && key(g.personId) === key(p.personId)) || (p.login && key(g.login) === key(p.login)))
      );
    },
    async reset() {
      Object.assign(this, { level: SHARING.defaultLevel, query: "", results: [], selected: [], error: "", addError: "", canManage: false });
      await Promise.all([this.loadRights(), this.loadGrantees()]);
    },
    async loadRights() {
      const id = this.dashboard.id;
      this.checkingRights = true;
      try {
        const [canManage, levels] = await Promise.all([sharingApi.canShare(id), sharingApi.listLevels(id).catch(() => SHARING.levels)]);
        this.canManage = canManage;
        this.levels = levels.length ? levels : SHARING.levels;
        if (!this.levels.some((l) => l.value === this.level)) this.level = this.levels[0].value;
      } finally {
        this.checkingRights = false;
      }
    },
    async loadGrantees() {
      this.loadingGrantees = true;
      try {
        this.grantees = await sharingApi.listGrantees(this.dashboard.id);
      } catch (e) {
        this.error = userMessage(e, ERROR_TEXT.loadAccess);
      } finally {
        this.loadingGrantees = false;
      }
    },
    async search(text) {
      const seq = ++this.searchSeq;
      if (!text || text.trim().length < 2) {
        this.results = [];
        return;
      }
      this.searching = true;
      try {
        const found = await peopleApi.search(text);
        if (seq === this.searchSeq) this.results = [...this.selected, ...found.filter((f) => !this.selected.some((s) => s.id === f.id))];
      } catch (e) {
        if (seq === this.searchSeq) this.addError = userMessage(e, ERROR_TEXT.searchPeople);
      } finally {
        if (seq === this.searchSeq) this.searching = false;
      }
    },
    validate() {
      const ids = new Set();
      for (const p of this.selected) {
        if (ids.has(p.id)) return "The same person is selected twice.";
        ids.add(p.id);
        if (this.isGranted(p)) return `${p.name || p.login} already has access.`;
        if (!p.personId) return `${p.name || "This person"} can't be identified on the platform.`;
      }
      if (!this.levels.some((l) => l.value === this.level)) return "Choose an access level.";
      return "";
    },
    async share() {
      this.error = "";
      this.addError = this.validate();
      if (this.addError) return;
      this.busy = true;
      try {
        await sharingApi.grant(this.dashboard.id, this.selected, this.level);
        const n = this.selected.length;
        toastBus.emit(`Shared with ${n} ${n === 1 ? "person" : "people"}.`, "success");
        this.selected = [];
        await this.loadGrantees();
        this.$emit("changed");
      } catch (e) {
        this.error = userMessage(e, ERROR_TEXT.share);
      } finally {
        this.busy = false;
      }
    },
    async changeLevel(g, level) {
      this.busy = true;
      this.error = "";
      try {
        await sharingApi.changeLevel(this.dashboard.id, g, level);
        await this.loadGrantees();
        toastBus.emit("Access level updated.", "success");
        this.$emit("changed");
      } catch (e) {
        this.error = userMessage(e, ERROR_TEXT.changeAccess);
      } finally {
        this.busy = false;
      }
    },
    async revoke(g) {
      this.busy = true;
      this.error = "";
      try {
        await sharingApi.revoke(this.dashboard.id, g);
        await this.loadGrantees();
        toastBus.emit(`Access removed for ${g.name || g.login}.`, "success");
        this.$emit("changed");
      } catch (e) {
        this.error = userMessage(e, ERROR_TEXT.removeAccess);
      } finally {
        this.busy = false;
      }
    },
  },
};
</script>

<style scoped>
.share-add {
  display: flex;
  gap: var(--dw-sp-2);
  align-items: flex-start;
}
.share-add__input {
  flex: 1;
  min-width: 0;
}
.share-add__level {
  flex: 0 0 190px;
}
.share-list-head {
  display: flex;
  align-items: center;
  gap: var(--dw-sp-2);
}
.share-list {
  border: 1px solid var(--dw-border);
  border-radius: var(--dw-radius);
}
.share-row {
  display: flex;
  align-items: center;
  gap: var(--dw-sp-3);
  padding: var(--dw-sp-2) var(--dw-sp-3);
  border-top: 1px solid var(--dw-divider);
}
.share-row:first-child {
  border-top: 0;
}
.share-row__text {
  flex: 1;
  min-width: 0;
}
.share-row__name {
  font-weight: var(--dw-fw-semibold);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.share-row__level {
  flex: 0 0 190px;
}
.share-avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--dw-primary-soft);
  color: var(--dw-primary);
  font-size: var(--dw-fs-xs);
  font-weight: var(--dw-fw-bold);
  display: grid;
  place-items: center;
  flex-shrink: 0;
}
.share-foot-note {
  margin-right: auto;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
@media (max-width: 520px) {
  .share-add {
    flex-direction: column;
    align-items: stretch;
  }
  .share-add__level {
    flex-basis: auto;
  }
}
</style>
