// Dashboard persistence on 3DEXPERIENCE Document objects (FR-06..FR-10, FR-13).
//
// • Each dashboard is one Document whose title is the dashboard name and whose
//   checked-in JSON file holds the definition (utils/dashboardSerializer.js).
// • Listing uses the federated search the widget already uses for its data. The
//   search returns only documents the current user may access, so owned and shared
//   dashboards both appear, and revoked access disappears with the platform index.
// • Access in the UI (owner vs. shared) is derived from the owner returned by the
//   platform. It only hides actions; every write is still checked by 3DSpace.

import http from "./httpClient.js";
import dashboardApi from "./dashboardApi.js";
import documentApi from "./documentApi.js";
import { identityOf } from "./activityApi.js";
import { ApiError, ERROR_CODES } from "./apiError";
import { DASHBOARD_DOC, PLATFORM } from "@/config/platformConfig";
import { serialize, parse } from "@/utils/dashboardSerializer";
import { useDashboardStore } from "@/store/dashboardStore";
import { firstValue } from "@/utils/searchResult";

const TYPE_KEY = "ds6w:what/ds6w:type";
// The index returns the same attribute under different names depending on the tenant
// (the widget's other searches already handle these variants), so all are requested and read.
const F = {
  label: ["dcterms:title", "ds6w:label", "ds6w:what/ds6w:label"],
  description: ["ds6w:description", "ds6w:what/ds6w:description", "dcterms:description"],
  owner: ["owner", "ds6w:who/ds6w:responsible", "ds6w:responsible", "ds6w:who/ds6w:originator", "ds6w:originator"],
  ownerName: ["ds6w:responsible", "ds6w:who/ds6w:responsible"],
  created: ["ds6w:created", "ds6w:when/ds6w:created"],
  modified: ["ds6w:modified", "ds6w:when/ds6w:modified"],
};
const PREDICATES = ["resourceid", ...new Set(Object.values(F).flat())];
// Note: a falsy value (0, false) counts as empty here, unlike firstTextOf().
const firstOf = (r, names) => names.map((n) => String(firstValue(r, n) || "")).find(Boolean) || "";
const norm = (s) => String(s || "").trim().toLowerCase();

// ---- description marker ----
const SEP = " · ";
export function withMarker(description) {
  const d = (description || "").trim();
  if (!DASHBOARD_DOC.marker) return d;
  return d ? `${DASHBOARD_DOC.marker}${SEP}${d}` : DASHBOARD_DOC.marker;
}
export function stripMarker(description) {
  const d = String(description || "");
  const m = DASHBOARD_DOC.marker;
  if (!m || !d.startsWith(m)) return d;
  return d.slice(m.length).replace(/^\s*·\s*/, "").trim();
}
// A result is dropped only when its description is known and lacks the marker. When the
// index did not return the description the search query (which includes the marker) is
// trusted; open() validates the file content anyway.
const isDashboardResult = (description) =>
  !DASHBOARD_DOC.marker || !description || String(description).startsWith(DASHBOARD_DOC.marker);

// Dashboards saved in this session. The federated search index is refreshed on a schedule,
// so a document created a moment ago may not be searchable yet; these entries are shown
// until the index returns them. In memory only — the Document object stays the source of truth.
const recentlySaved = new Map();
export function rememberSaved(meta) {
  if (meta?.id) recentlySaved.set(meta.id, { ...meta, pendingIndex: true });
  registry.add(meta?.id);
}
export function forgetSaved(id) {
  recentlySaved.delete(id);
  registry.remove(id);
}

// Ids of the dashboards this user created from this widget, kept in a hidden widget
// preference (stored by 3DDashboard on the platform, not in the browser). It is only a
// lookup list so that the user's own dashboards can be read directly by id while the
// search index has not picked them up yet; each id is re-read from 3DSpace with the
// user's own access rights, and ids that no longer resolve are dropped.
const REGISTRY_PREF = "dw_dashboard_ids";
const REGISTRY_MAX = 50;
const registry = {
  widget() {
    const w = window.widget;
    if (!w?.getValue || !w?.setValue) return null;
    if (w.getPreference && !w.getPreference(REGISTRY_PREF) && w.addPreference) {
      w.addPreference({ name: REGISTRY_PREF, type: "hidden", label: "Saved dashboards", defaultValue: "" });
    }
    return w;
  },
  ids() {
    try {
      const raw = this.widget()?.getValue(REGISTRY_PREF) || "";
      return raw.split(",").map((x) => x.trim()).filter((x) => /^[A-Za-z0-9.:-]{8,64}$/.test(x));
    } catch (e) {
      return [];
    }
  },
  save(ids) {
    try {
      this.widget()?.setValue(REGISTRY_PREF, [...new Set(ids)].slice(-REGISTRY_MAX).join(","));
    } catch (e) {
      /* preference storage unavailable: search results are still used */
    }
  },
  add(id) {
    if (id && !this.ids().includes(id)) this.save([...this.ids(), id]);
  },
  remove(id) {
    if (id) this.save(this.ids().filter((x) => x !== id));
  },
};

// ---- ownership ----
export function isOwnedByCurrentUser(owner) {
  const user = useDashboardStore().getUser || {};
  const mine = new Set([user.login, ...identityOf()].map(norm).filter(Boolean));
  return !!owner && mine.has(norm(owner));
}

export function accessOf(owner) {
  return isOwnedByCurrentUser(owner) ? "owner" : "shared";
}

function toListItem(r) {
  const description = firstOf(r, F.description);
  const owner = firstOf(r, F.owner);
  return {
    id: String(firstValue(r, "resourceid") || ""),
    name: firstOf(r, F.label) || "Untitled dashboard",
    description: stripMarker(description),
    isDashboard: isDashboardResult(description),
    owner,
    ownerName: firstOf(r, F.ownerName) || owner,
    access: accessOf(owner),
    created: firstOf(r, F.created),
    modified: firstOf(r, F.modified),
  };
}

// Search queries tried in order until one returns results. The first follows the pattern the
// widget already uses for Document dashboards (type query from the type configuration + type
// refine) with the marker as a keyword; the second matches the marker on the description
// predicate, for indexes that do not include the description in full-text search.
function searchQueries() {
  const typeCfg = useDashboardStore().getTypeConfig.find((t) => t.refineValue === DASHBOARD_DOC.type || t.name === DASHBOARD_DOC.type);
  const base = typeCfg?.query || "";
  const m = DASHBOARD_DOC.marker;
  if (!m) return [base || `"${DASHBOARD_DOC.type}"`];
  return [[base, m].filter(Boolean).join(" AND "), [base, `[ds6w:description]:"${m}"`].filter(Boolean).join(" AND ")];
}

function searchPayload(query, nextStart, ordered = true) {
  const p = dashboardApi.buildPayload(DASHBOARD_DOC.type, {}, DASHBOARD_DOC.pageSize, nextStart);
  p.query = query;
  p.refine = dashboardApi.refineOf(TYPE_KEY, DASHBOARD_DOC.type);
  p.select_predicate = PREDICATES;
  p.select_file = [];
  p.source = ["3dspace"];
  if (ordered) {
    p.order_field = "ds6w:modified";
    p.order_by = "desc";
  }
  if (!nextStart) p.start = "0";
  return p;
}

// One search page; retries once without ordering when the index rejects the sort field.
async function searchPage(query, nextStart) {
  try {
    return await http.post(PLATFORM.federatedSearch, searchPayload(query, nextStart));
  } catch (e) {
    if (nextStart) throw e;
    return http.post(PLATFORM.federatedSearch, searchPayload(query, nextStart, false));
  }
}

export default {
  // Every dashboard document the current user can access (owned + shared).
  async list() {
    const items = new Map();
    let truncated = false;
    let returned = 0;
    let variant = 0;
    const queries = searchQueries();
    for (variant = 0; variant < queries.length; variant++) {
      let next = null;
      for (let page = 0; page * DASHBOARD_DOC.pageSize < DASHBOARD_DOC.maxResults; page++) {
        const json = await searchPage(queries[variant], next);
        const results = json?.results || [];
        returned += results.length;
        results.map(toListItem).forEach((it) => it.id && it.isDashboard && items.set(it.id, it));
        next = json?.infos?.next_start;
        if (results.length < DASHBOARD_DOC.pageSize || !next) break;
        if ((page + 1) * DASHBOARD_DOC.pageSize >= DASHBOARD_DOC.maxResults) truncated = true;
      }
      if (returned) break; // this query works on this index; don't try the next one
    }
    // Add dashboards saved in this session that the index does not return yet.
    recentlySaved.forEach((meta, id) => {
      if (items.has(id)) recentlySaved.delete(id);
      else items.set(id, { ...meta, ownerName: meta.ownerName || meta.owner, pendingIndex: true });
    });
    // Read the user's own dashboards directly by id when the index does not return them yet
    // (e.g. after a widget reload, before the next index refresh).
    const missing = registry.ids().filter((id) => !items.has(id));
    let fromRegistry = 0;
    await Promise.all(
      missing.map(async (id) => {
        try {
          const doc = await documentApi.get(id);
          if (!String(doc.description || "").startsWith(DASHBOARD_DOC.marker || "")) return registry.remove(id);
          items.set(id, { ...this.metaOf(doc), pendingIndex: true });
          fromRegistry++;
        } catch (e) {
          // deleted or no longer accessible: forget it; keep it on network errors
          if (e?.code === ERROR_CODES.NOT_FOUND || e?.code === ERROR_CODES.FORBIDDEN) registry.remove(id);
        }
      }),
    );
    // Diagnostic counts only (no names, ids or tokens).
    console.info(
      `[dashboards] search returned ${returned} document(s) (query ${Math.min(variant + 1, queries.length)} of ${queries.length}); ` +
        `${fromRegistry} read directly (not indexed yet); ${items.size} dashboard(s) listed`,
    );
    const list = [...items.values()].sort((a, b) => String(b.modified).localeCompare(String(a.modified)));
    list.truncated = truncated;
    return list;
  },

  // Reads the document, downloads its definition and returns { meta, state }.
  async open(id) {
    const doc = await documentApi.get(id);
    const file = doc.files.find((f) => f.title === DASHBOARD_DOC.fileName) || doc.files.find((f) => /\.json$/i.test(f.title));
    if (!file) throw new ApiError(ERROR_CODES.MALFORMED, { message: "This document has no dashboard definition file." });
    const content = await documentApi.downloadFile(doc.id, file.id);
    const state = parse(content);
    return { meta: this.metaOf(doc), state };
  },

  metaOf(doc) {
    return {
      id: doc.id,
      name: doc.title,
      description: stripMarker(doc.description),
      owner: doc.owner,
      ownerName: doc.ownerName || doc.owner,
      access: accessOf(doc.owner),
      // Effective rights reported by 3DSpace (null when not returned).
      canModify: doc.canModify,
      canDelete: doc.canDelete,
      modified: doc.modified,
      created: doc.created,
      doc,
    };
  },

  // Creates a new dashboard document in the collaborative space of `ctx`.
  async create({ name, description, state, ctx }) {
    const content = serialize(state);
    const doc = await documentApi.create(
      {
        title: name,
        description: withMarker(description),
        type: DASHBOARD_DOC.type,
        policy: DASHBOARD_DOC.policy,
        fileName: DASHBOARD_DOC.fileName,
        content,
      },
      ctx,
    );
    // Make sure the platform kept the name and description the user typed. If the created
    // document came back with another title (e.g. an auto-generated document number) or
    // without the dashboard marker, set them explicitly with a modify call.
    let saved = doc;
    if (doc.title !== name || !String(doc.description || "").startsWith(DASHBOARD_DOC.marker || "")) {
      saved = await documentApi.update(doc, { title: name, description: withMarker(description) }, ctx).catch(() => doc);
    }
    // The UI always shows the name the user entered, never the document number.
    const meta = { ...this.metaOf(saved), name, description: (description || "").trim() };
    if (!meta.owner) meta.access = "owner"; // just created by this user
    rememberSaved(meta);
    return meta;
  },

  // Updates an owned dashboard. Fails with CONFLICT if it changed since it was opened (NFR-08).
  async update(meta, { name, description, state }) {
    const current = await documentApi.get(meta.id);
    if (meta.modified && current.modified && current.modified !== meta.modified) {
      throw new ApiError(ERROR_CODES.CONFLICT);
    }
    const doc = await documentApi.update(current, {
      title: name,
      description: withMarker(description),
      ...(state && { fileName: DASHBOARD_DOC.fileName, content: serialize(state) }),
    });
    const refreshed = await documentApi.get(meta.id).catch(() => doc);
    const saved = this.metaOf(refreshed);
    if (recentlySaved.has(saved.id)) rememberSaved(saved);
    return saved;
  },

  async rename(meta, { name, description }) {
    return this.update(meta, { name, description });
  },

  // Copies any accessible dashboard into a new document owned by the current user.
  async duplicate(meta, { name, ctx } = {}) {
    const { state } = await this.open(meta.id);
    return this.create({ name: name || `Copy of ${meta.name}`, description: meta.description, state, ctx });
  },

  async remove(meta) {
    await documentApi.remove(meta.id);
    forgetSaved(meta.id);
  },
};
