<template>
  <div class="db-wrap">
    <div class="topbar">
      <div class="topbar-left">
        <button type="button" class="btn-outline btn-sm" @click="$emit('go-home')">
          <v-icon icon="mdi-home-outline" size="14" /> {{ text.home }}
        </button>

        <span class="label">{{ text.period }}</span>
        <v-menu>
          <template #activator="{ props }">
            <button type="button" class="type-pill" v-bind="props" title="Change period" :aria-label="`${text.period}: ${period.label}`">
              {{ period.label }} <v-icon icon="mdi-chevron-down" size="16" />
            </button>
          </template>
          <v-list density="compact">
            <v-list-item
              v-for="p in periods"
              :key="p.id"
              :title="p.label"
              :active="p.id === periodId"
              color="primary"
              @click="periodId = p.id"
            />
          </v-list>
        </v-menu>

        <v-menu v-model="menu" :close-on-content-click="false" location="bottom start">
          <template #activator="{ props }">
            <button type="button" class="filter-pill" v-bind="props" :aria-label="`${text.filters}, ${activeChips.length} active`">
              <v-icon icon="mdi-filter-variant" size="16" /> {{ text.filters }} ({{ activeChips.length }})
            </button>
          </template>

          <div class="fp-card">
            <div class="fp-head">
              <button type="button" class="icon-btn icon-btn--sm" aria-label="Close filters" @click="menu = false"><v-icon icon="mdi-close" /></button>
            </div>

            <div class="fp-group">
              <div class="fp-label">{{ text.search }}</div>
              <v-text-field
                v-model="draft.search"
                density="compact"
                variant="outlined"
                hide-details
                :placeholder="text.searchHint"
              />
            </div>

            <div v-for="g in chipGroups" :key="g.key" class="fp-group">
              <div class="fp-label">{{ g.label }}</div>
              <div class="fp-chips">
                <button
                  v-for="o in g.options"
                  :key="o.value"
                  type="button"
                  class="fp-chip"
                  :class="{ active: draft[g.key].includes(o.value) }"
                  :aria-pressed="draft[g.key].includes(o.value) ? 'true' : 'false'"
                  @click="toggleDraft(g.key, o.value)"
                >{{ o.label }}</button>
              </div>
            </div>

            <div v-for="d in dateGroups" :key="d.key" class="fp-group">
              <div class="fp-label">{{ d.label }}</div>
              <div class="fp-chips mb-2">
                <button
                  v-for="p in presets"
                  :key="p.id"
                  type="button"
                  class="fp-chip"
                  :class="{ active: isPreset(d, p) }"
                  :aria-pressed="isPreset(d, p) ? 'true' : 'false'"
                  @click="setPreset(d, p)"
                >{{ p.label }}</button>
              </div>
              <div class="fp-date-row">
                <input v-model="draft[d.from]" type="date" class="fp-date-input" :aria-label="`${d.label} from`" :max="draft[d.to] || undefined" />
                <span class="fp-date-sep">to</span>
                <input v-model="draft[d.to]" type="date" class="fp-date-input" :aria-label="`${d.label} to`" :min="draft[d.from] || undefined" />
              </div>
            </div>

            <button type="button" class="btn-primary fp-btn" @click="applyDraft">{{ text.apply }}</button>
          </div>
        </v-menu>
      </div>

      <div class="topbar-right">
        <span v-if="!loading" class="refreshed">{{ text.refreshed }} {{ lastRefreshed }}</span>
        <button type="button" class="icon-btn" aria-label="Refresh activity" title="Refresh" :disabled="loading" @click="load">
          <v-icon icon="mdi-refresh" :class="{ spin: loading }" />
        </button>
      </div>
    </div>

    <div v-if="activeChips.length" class="chips-row">
      <span v-for="c in activeChips" :key="c.id" class="dw-chip">
        {{ c.label }}
        <button type="button" class="dw-chip__remove" :aria-label="`Remove filter ${c.label}`" @click="c.remove()"><v-icon icon="mdi-close" size="14" /></button>
      </span>
      <button type="button" class="btn-ghost btn-sm" @click="clearAll">{{ text.clearAll }}</button>
    </div>

    <div class="content">
      <div class="main">
        <!-- one calm loading card instead of numbers jumping around -->
        <div v-if="loading && !rows.length" class="load-card">
          <v-icon icon="mdi-account-clock-outline" size="38" color="primary" />
          <div class="load-title">{{ text.loadingTitle }}</div>
          <div class="load-bar" :class="{ wait: !progress.target }"><span :style="{ width: loadPct + '%' }" /></div>
          <div class="load-sub">{{ progressText }}</div>
        </div>

        <StateMessage
          v-else-if="error"
          icon="mdi-power-plug-off-outline"
          tone="error"
         
          :title="text.errorTitle"
          :message="error"
          :action-label="text.retry"
          @action="load"
        />
        <StateMessage v-else-if="!rows.length" icon="mdi-package-variant" :title="text.emptyTitle" :message="text.emptyMessage" />
        <StateMessage
          v-else-if="!filtered.length"
          icon="mdi-filter-off-outline"
         
         
          :title="text.noMatchTitle"
          :message="text.noMatchMessage"
          :action-label="text.clearAll"
          @action="clearAll"
        />

        <template v-else>
          <div v-if="hasMore || loading" class="warn">
            <v-icon icon="mdi-information-outline" size="16" />
            <template v-if="loading">
              <span>{{ progressText }}</span>
              <span class="warn-bar" :class="{ wait: !progress.target }"><i :style="{ width: loadPct + '%' }" /></span>
            </template>
            <template v-else>
              <span>{{ text.partial.replace("{n}", rows.length.toLocaleString()) }}</span>
              <button type="button" class="warn-btn" @click="more(chunk)">{{ text.loadNext.replace("{n}", chunk) }}</button>
              <button type="button" class="warn-btn" @click="more(Infinity)">{{ text.loadAll }}</button>
            </template>
          </div>

          <div class="hero">
            <div class="hero-main">
              <div class="hero-eyebrow">{{ text.heroTitle }}</div>
              <div class="hero-user">{{ identity[0] || "–" }}</div>
              <div class="hero-sub">{{ text.heroSub }}</div>
            </div>
            <div class="hero-stats">
              <component
                :is="k.kind ? 'button' : 'div'"
                v-for="k in heroStats"
                :key="k.label"
                class="hstat"
                :class="{ click: k.kind, on: k.kind && drill && drill.kind === k.kind && drill.val === k.val }"
                :style="{ '--c': k.color }"
                @click="k.kind && openDrill(k.kind, k.val, k.label, true)"
              >
                <span class="hstat-icon"><v-icon :icon="k.icon" size="20" /></span>
                <span class="hstat-body">
                  <span class="hstat-value">{{ k.value }}</span>
                  <span class="hstat-label">{{ k.label }}</span>
                  <span v-if="k.sub" class="hstat-sub">{{ k.sub }}</span>
                </span>
              </component>
            </div>
          </div>

          <!-- one chart per row; a chart without data is not shown -->
          <div class="stack">
            <div v-for="id in visiblePanels" :key="id" class="panel">
              <div class="panel-head">
                <div class="panel-title"><v-icon :icon="panelIcon[id]" size="18" />{{ panelTitle[id] }}</div>
                <div class="panel-actions">
                  <button type="button" class="icon-btn icon-btn--sm" :aria-label="text.refreshChart" :title="text.refreshChart" @click="load"><v-icon icon="mdi-refresh" /></button>
                  <button type="button" class="icon-btn icon-btn--sm" :aria-label="text.moveUp" :title="text.moveUp" @click="movePanel(id, -1)"><v-icon icon="mdi-arrow-up" /></button>
                  <button type="button" class="icon-btn icon-btn--sm" :aria-label="text.moveDown" :title="text.moveDown" @click="movePanel(id, 1)"><v-icon icon="mdi-arrow-down" /></button>
                  <button type="button" class="icon-btn icon-btn--sm" :aria-label="text.removeChart" :title="text.removeChart" @click="hidden.push(id)"><v-icon icon="mdi-delete-outline" /></button>
                </div>
              </div>

              <div v-if="id === 'type'" class="donut-row">
                <div class="chart-container">
                  <apexchart type="donut" :height="typeHeight" :options="donutOptions" :series="typeSeries" />
                </div>
                <div class="legend" :style="{ maxHeight: typeHeight + 'px' }">
                  <div
                    v-for="(t, i) in typeSummary.byType"
                    :key="t[0]"
                    class="legend-row"
                    :class="{ dim: drill && drill.kind === 'type' && drill.val !== t[0] }"
                    role="button"
                    tabindex="0"
                    @click="openDrill('type', t[0])"
                    @keydown.enter.prevent="openDrill('type', t[0])"
                    @keydown.space.prevent="openDrill('type', t[0])"
                  >
                    <span class="dot" :style="{ background: palette[i % palette.length] }" />
                    <span class="legend-label">{{ t[0] }}</span>
                    <span class="legend-value">{{ t[1].toLocaleString() }} ({{ pct(t[1], typeSummary.total) }}%)</span>
                  </div>
                </div>
              </div>
              <apexchart v-else-if="id === 'status'" type="bar" :height="statusHeight" :options="barOptions" :series="statusSeries" />
              <apexchart v-else-if="id === 'time'" type="area" height="340" :options="areaOptions" :series="areaSeries" />
              <apexchart v-else type="bar" height="320" :options="ageOptions" :series="ageSeries" />
            </div>
          </div>

          <button v-if="hidden.length" type="button" class="warn-btn restore" @click="hidden = []">
            {{ text.restoreCharts }} ({{ hidden.length }})
          </button>

          <div class="foot">
            {{ text.matching }}: <b>{{ identity.join(", ") || "–" }}</b> {{ text.matchingHint }}
          </div>
        </template>
      </div>

      <ActivityDrillPanel v-if="drill" :label="drill.label" :note="drillNote" :rows="drillRows" @close="drill = null" />
    </div>
  </div>
</template>

<script>
import VueApexCharts from "vue3-apexcharts";
import ActivityDrillPanel from "@/components/dashboard/ActivityDrillPanel.vue";
import StateMessage from "@/components/common/StateMessage.vue";
import { createActivityLoader, identityOf } from "@/services/activityApi";
import { applyFilters, summarize, timeline, ageBuckets, inBucket } from "@/utils/activityRules";
import * as D from "@/utils/dashboardData";
import { ACTIVITY_TEXT } from "@/utils/uiText";

const { ACTIVITY_PERIODS, DEFAULT_ACTIVITY_PERIOD, ACTIVITY_DATE_PRESETS, ACTIVITY_AGE_COLORS, COLORS, PALETTE } = D;
const { ACTIVITY_CHUNK } = D;
import { toastBus } from "@/components/common/toastBus";
import { logError } from "@/utils/logger";

const DAY = 86400000;
let loader = null; // current chunked loader (not reactive on purpose)
const emptyFilters = () => ({
  search: "", type: [], status: [], role: [],
  createdFrom: "", createdTo: "", modifiedFrom: "", modifiedTo: "",
});
const cloneFilters = (f) => ({ ...f, type: [...f.type], status: [...f.status], role: [...f.role] });
const isoDaysAgo = (days) => {
  const d = new Date(Date.now() - days * DAY);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
};
const modTime = (r) => (r.modified ? new Date(r.modified).getTime() || 0 : 0);
const AGE_MAX = [7, 30, 90, Infinity]; // same bands as ageBuckets()
const ageIdx = (r) => AGE_MAX.findIndex((m) => (Date.now() - modTime(r)) / DAY <= m);
const pctOf = (n, total) => (total ? Math.round((n / total) * 100) : 0);
const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));
const GRID = { strokeDashArray: 4 };
const INT = { min: 0, forceNiceScale: true, labels: { formatter: (v) => Math.round(v) } };

export default {
  name: "MyActivityView",
  components: { apexchart: VueApexCharts, StateMessage, ActivityDrillPanel },
  emits: ["go-home"],
  data() {
    return {
      text: ACTIVITY_TEXT,
      periods: ACTIVITY_PERIODS,
      presets: ACTIVITY_DATE_PRESETS,
      roles: [{ id: "owner", label: ACTIVITY_TEXT.assignedLabel, icon: "mdi-account-check-outline", color: COLORS.blue, short: "Assigned" }], // only items assigned to me
      order: ["type", "status", "time", "age"],
      hidden: [],
      palette: PALETTE,
      chunk: ACTIVITY_CHUNK,
      dateGroups: [
        { key: "created", label: ACTIVITY_TEXT.created, from: "createdFrom", to: "createdTo" },
        { key: "modified", label: ACTIVITY_TEXT.modified, from: "modifiedFrom", to: "modifiedTo" },
      ],
      periodId: DEFAULT_ACTIVITY_PERIOD,
      filters: emptyFilters(),
      draft: emptyFilters(),
      menu: false,
      drill: null, // { kind: 'type'|'status'|'age'|'role'|'time', val, label }
      rows: [],
      totals: {}, // exact counts per role from the search
      hasMore: false,
      progress: { loaded: 0, target: 0 },
      loading: true,
      error: "",
      lastRefreshed: "–",
      req: 0,
    };
  },
  computed: {
    identity: () => identityOf(),
    period() {
      return this.periods.find((p) => p.id === this.periodId);
    },
    roleById() {
      return Object.fromEntries(this.roles.map((r) => [r.id, r]));
    },
    loadPct() {
      const { loaded, target } = this.progress;
      return target ? Math.min(100, Math.round((loaded / target) * 100)) : 0;
    },
    progressText() {
      return this.text.loadingMessage; // no counting numbers while loading
    },
    heroStats() {
      const [mine, recent] = this.kpis;
      return [
        { ...mine, sub: mine.sub === this.text.tileHint ? "" : mine.sub },
        { ...recent, sub: "" },
        { label: this.text.typesLabel, icon: "mdi-shape-outline", color: COLORS.purple, value: this.typeSummary.byType.length.toLocaleString() },
      ];
    },
    panelIcon: () => ({ type: "mdi-chart-donut", status: "mdi-chart-bar", time: "mdi-chart-areaspline", age: "mdi-clock-outline" }),
    panelTitle() {
      return { type: this.text.byType, status: this.text.byStatus, time: this.text.overTime, age: this.text.byAge };
    },
    visiblePanels() {
      const has = { type: this.typeSummary.byType.length, status: this.hasStatus, time: this.line.labels.length, age: this.hasAges };
      return this.order.filter((id) => has[id] && !this.hidden.includes(id));
    },
    typeOptions() {
      return [...new Set(this.rows.map((r) => r.type))].sort();
    },
    statusOptions() {
      return [...new Set(this.rows.map((r) => r.status))].sort();
    },
    chipGroups() {
      return [
        { key: "type", label: this.text.typeLabel, options: this.typeOptions.map((v) => ({ value: v, label: v })) },
        { key: "status", label: this.text.statusLabel, options: this.statusOptions.map((v) => ({ value: v, label: v })) },
      ];
    },
    activeChips() {
      const f = this.filters;
      const out = [];
      if (f.search) out.push({ id: "search", label: `${this.text.search}: ${f.search}`, remove: () => (f.search = "") });
      ["type", "status", "role"].forEach((k) =>
        f[k].forEach((v) =>
          out.push({
            id: k + v,
            label: `${this.text[k + "Label"]}: ${k === "role" ? this.roleById[v].label : v}`,
            remove: () => (f[k] = f[k].filter((x) => x !== v)),
          }),
        ),
      );
      this.dateGroups.forEach((d) => {
        if (f[d.from] || f[d.to])
          out.push({
            id: d.key,
            label: `${d.label}: ${f[d.from] || "…"} → ${f[d.to] || "…"}`,
            remove: () => {
              f[d.from] = "";
              f[d.to] = "";
            },
          });
      });
      return out;
    },
    filtered() {
      return applyFilters(this.rows, this.filters);
    },
    // every chart follows every filter
    typeRows() {
      return this.filtered;
    },
    statusRows() {
      return this.filtered;
    },
    summary() {
      return summarize(this.filtered);
    },
    typeSummary() {
      return summarize(this.typeRows);
    },
    statusSummary() {
      return summarize(this.statusRows);
    },
    line() {
      return timeline(this.filtered);
    },
    ages() {
      return ageBuckets(this.filtered);
    },
    // a chart with nothing to show is hidden
    hasStatus() {
      return this.statusSummary.byStatus.some((x) => x[0] !== "–");
    },
    hasAges() {
      return this.ages.some((x) => x[1] > 0);
    },
    // charts grow with the amount of data
    typeHeight() {
      return clamp(this.typeSummary.byType.length * 30 + 20, 260, 420);
    },
    statusHeight() {
      return clamp(this.statusSummary.byStatus.length * 32 + 80, 300, 1000);
    },
    drillRows() {
      const d = this.drill;
      if (!d) return [];
      const src = d.kind === "type" ? this.typeRows : d.kind === "status" ? this.statusRows : this.filtered;
      const base = [...src].sort(
        (a, b) => modTime(b) - modTime(a),
      );
      return base.filter((r) =>
        d.kind === "type" ? r.type === d.val
        : d.kind === "status" ? r.status === d.val
        : d.kind === "role" ? r.roles.includes(d.val)
        : d.kind === "time" ? r.roles.includes(d.val.role) && inBucket(r, d.val.key, d.val.g)
        : ageIdx(r) === d.val,
      );
    },
    drillNote() {
      const d = this.drill;
      if (!d || d.kind !== "role") return "";
      const total = this.totals[d.val];
      const have = this.rows.filter((r) => r.roles.includes(d.val)).length;
      return total != null && have < total
        ? this.text.drillPartial.replace("{a}", have.toLocaleString()).replace("{b}", total.toLocaleString())
        : "";
    },
    kpis() {
      const s = this.summary;
      const exact = !this.activeChips.length; // no filters: show the exact total from the search
      return [
        ...this.roles.map((r) => {
          const total = exact ? this.totals[r.id] : null;
          const loaded = s[r.id];
          return {
            kind: "role", val: r.id, label: r.label, icon: r.icon, color: r.color,
            value: (total != null ? total : loaded).toLocaleString(),
            pct: total ? Math.min(100, Math.round((loaded / total) * 100)) : 100,
            sub: total != null && loaded < total ? `${loaded.toLocaleString()} ${this.text.loadedSuffix}` : this.text.tileHint,
          };
        }),
        { kind: "age", val: 0, label: this.text.recentLabel, icon: "mdi-update", color: COLORS.orange, value: this.ages[0][1].toLocaleString(), pct: pctOf(this.ages[0][1], s.total), sub: this.text.tileHint },
      ];
    },
    typeSeries() {
      return this.typeSummary.byType.map((x) => x[1]);
    },
    statusSeries() {
      return [{ name: this.text.items, data: this.statusSummary.byStatus.map((x) => x[1]) }];
    },
    areaSeries() {
      return [
        { name: this.roleName("owner"), data: this.line.owner },
      ];
    },
    ageSeries() {
      return [{ name: this.text.items, data: this.ages.map((x) => x[1]) }];
    },
    donutOptions() {
      return {
        chart: {
          toolbar: { show: false },
          events: { dataPointSelection: (e, c, cfg) => this.openDrill("type", this.typeSummary.byType[cfg.dataPointIndex]?.[0]) },
        },
        labels: this.typeSummary.byType.map((x) => x[0]),
        colors: PALETTE,
        legend: { show: false },
        dataLabels: { enabled: false },
        stroke: { width: 2, colors: ["#FFFFFF"] }, // 2px surface gap between segments
        plotOptions: { pie: { donut: { size: "58%" } } },
      };
    },
    barOptions() {
      return {
        chart: {
          toolbar: { show: false },
          events: { dataPointSelection: (e, c, cfg) => this.openDrill("status", this.statusSummary.byStatus[cfg.dataPointIndex]?.[0]) },
        },
        plotOptions: { bar: { horizontal: true, borderRadius: 4, barHeight: "62%" } },
        colors: [COLORS.blue],
        fill: { opacity: 1 },
        xaxis: { categories: this.statusSummary.byStatus.map((x) => x[0]), labels: { formatter: (v) => Math.round(v) } },
        dataLabels: { enabled: true, style: { fontSize: "12px" } },
        grid: GRID,
      };
    },
    areaOptions() {
      return {
        chart: {
          toolbar: { show: false },
          events: {
            // click a point: open the items of that role created in that period
            dataPointSelection: (e, c, cfg) => {
              const role = "owner";
              const key = this.line.keys[cfg.dataPointIndex];
              if (!role || key == null) return;
              this.openDrill("time", { role, key, g: this.line.g }, `${this.roleName(role)} · ${this.line.labels[cfg.dataPointIndex]}`, true);
            },
          },
        },
        colors: [this.roleColor("owner")],
        stroke: { curve: "smooth", width: 2 },
        markers: { size: 4, hover: { size: 6 } },
        dataLabels: { enabled: false },
        grid: GRID,
        xaxis: { categories: this.line.labels, tickAmount: Math.min(12, this.line.labels.length) },
        yaxis: INT,
        legend: { show: false },
      };
    },
    ageOptions() {
      return {
        chart: {
          toolbar: { show: false },
          events: {
            dataPointSelection: (e, c, cfg) =>
              this.openDrill("age", cfg.dataPointIndex, this.ages[cfg.dataPointIndex][0]),
          },
        },
        plotOptions: { bar: { distributed: true, borderRadius: 4, columnWidth: "40%" } },
        colors: ACTIVITY_AGE_COLORS,
        fill: { opacity: 1 },
        xaxis: { categories: this.ages.map((x) => x[0]) },
        yaxis: INT,
        legend: { show: false },
        dataLabels: { enabled: true },
        grid: GRID,
      };
    },
  },
  watch: {
    periodId() {
      this.load();
    },
    menu(open) {
      if (open) this.draft = cloneFilters(this.filters); // popup always starts from what is applied
    },
  },
  mounted() {
    this.load();
  },
  methods: {
    roleName(id) {
      return this.roles.find((r) => r.id === id)?.label || id;
    },
    roleColor(id) {
      return this.roles.find((r) => r.id === id)?.color || COLORS.blue;
    },
    movePanel(id, dir) {
      const vis = this.visiblePanels;
      const other = vis[vis.indexOf(id) + dir];
      if (!other) return;
      const o = [...this.order];
      const i = o.indexOf(id), j = o.indexOf(other);
      [o[i], o[j]] = [o[j], o[i]];
      this.order = o;
    },
    pct: (n, total) => (total ? Math.round((n / total) * 100) : 0),
    openDrill(kind, val, label = val, plain = false) {
      if (val === undefined || val === null) return;
      const name = { type: this.text.typeLabel, status: this.text.statusLabel, age: this.text.byAge }[kind];
      this.drill = { kind, val, label: plain || !name ? label : `${name}: ${label}` };
    },
    toggleDraft(key, val) {
      const a = this.draft[key];
      this.draft[key] = a.includes(val) ? a.filter((x) => x !== val) : [...a, val];
    },
    isPreset(d, p) {
      return p.days
        ? !this.draft[d.to] && this.draft[d.from] === isoDaysAgo(p.days)
        : !this.draft[d.from] && !this.draft[d.to];
    },
    setPreset(d, p) {
      this.draft[d.from] = p.days ? isoDaysAgo(p.days) : "";
      this.draft[d.to] = "";
    },
    applyDraft() {
      this.filters = cloneFilters(this.draft);
      this.menu = false;
    },
    clearAll() {
      this.filters = emptyFilters();
    },
    async load() {
      const id = ++this.req; // a newer load invalidates older ones
      this.rows = [];
      this.drill = null;
      this.totals = {};
      this.hasMore = false;
      this.progress = { loaded: 0, target: 0 };
      this.error = "";
      this.loading = true;
      try {
        loader = createActivityLoader(this.period);
        await this.pull(id, ACTIVITY_CHUNK);
      } catch (e) {
        logError("activity", "Loading activity failed:", e);
        // shown on the page (StateMessage with Retry); no toast, to avoid a double message
        if (id === this.req) this.error = e.message === "NO_USER" ? this.text.noUser : this.text.errorMessage;
      } finally {
        if (id === this.req) this.loading = false;
      }
    },
    // fetches up to `limit` more items per role; the screen updates once, when the chunk is complete
    async pull(id, limit) {
      const l = loader;
      await l.loadMore(limit, (p) => {
        if (id === this.req) this.progress = p;
      });
      if (id === this.req) {
        this.rows = l.rows();
        this.totals = l.totals();
        this.hasMore = l.hasMore();
        this.lastRefreshed = new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
      }
    },
    async more(limit) {
      if (this.loading || !loader) return;
      const id = this.req;
      this.progress = { loaded: 0, target: 0 };
      this.loading = true;
      try {
        await this.pull(id, limit);
      } catch (e) {
        logError("activity", "Loading more activity failed:", e);
        toastBus.emit(this.text.errorTitle, "error");
      } finally {
        if (id === this.req) this.loading = false;
      }
    },
  },
};
</script>

