<template>
  <v-menu v-model="open" :close-on-content-click="false" location="bottom start">
    <template #activator="{ props }">
      <button type="button" class="filter-pill" v-bind="props" :title="text.activatorTitle" :aria-label="`Filters, ${activeCount} active`">
        <v-icon icon="mdi-filter-variant" size="16" /> Filters ({{ activeCount }})
      </button>
    </template>

    <div class="fp-card">
      <div class="fp-head">
        <span class="dw-section-title">Filters</span>
        <button type="button" class="icon-btn icon-btn--sm" aria-label="Close filters" @click="open = false">
          <v-icon icon="mdi-close" />
        </button>
      </div>

      <div v-for="g in groups" :key="g.key" class="fp-group">
        <div class="fp-label">{{ g.label }}</div>

        <!-- chip: pick from known values (status/policy/owner) -->
        <div v-if="g.type === 'chip'" class="fp-chips">
          <button
            v-for="opt in g.options"
            :key="opt.raw"
            type="button"
            class="fp-chip"
            :class="{ active: sel[g.key].some((s) => s.raw === opt.raw) }"
            :aria-pressed="sel[g.key].some((s) => s.raw === opt.raw) ? 'true' : 'false'"
            @click="toggleChip(g.key, opt)"
          >{{ opt.label }}</button>
        </div>

        <!-- date-range: quick chip presets, or a plain native from/to range -->
        <div v-else-if="g.type === 'date-range'">
          <div class="fp-chips mb-2">
            <button
              v-for="p in datePresets"
              :key="p.key"
              type="button"
              class="fp-chip"
              :class="{ active: sel[g.key].preset === p.key }"
              :aria-pressed="sel[g.key].preset === p.key ? 'true' : 'false'"
              @click="applyPreset(g.key, p.key)"
            >{{ p.label }}</button>
          </div>
          <div v-if="sel[g.key].preset === 'custom'" class="fp-date-row">
            <input v-model="sel[g.key].from" type="date" class="fp-date-input" :aria-label="`${g.label} from`" :max="sel[g.key].to || undefined" />
            <span class="fp-date-sep">to</span>
            <input v-model="sel[g.key].to" type="date" class="fp-date-input" :aria-label="`${g.label} to`" :min="sel[g.key].from || undefined" />
          </div>
        </div>

        <!-- text: free-text contains match -->
        <div v-else class="fp-text-row">
          <v-text-field v-model="sel[g.key]" density="compact" variant="outlined" hide-details :placeholder="`Search ${g.label}...`" />
        </div>
      </div>

      <div class="fp-foot">
        <button type="button" class="btn-primary" @click="apply">{{ text.applyLabel }}</button>
      </div>
    </div>
  </v-menu>
</template>

<script>
import { FILTER_GROUPS } from "@/utils/dashboardData";
import { FILTER_POPUP_TEXT } from "@/utils/uiText";

function emptyValue(type) {
  if (type === "chip") return [];
  if (type === "date-range") return { preset: "", from: "", to: "" };
  return "";
}

function isoDaysAgo(days) {
  const d = new Date();
  d.setDate(d.getDate() - days);
  return d.toISOString().slice(0, 10);
}

const DATE_PRESETS = [
  { key: "7d", label: "Last 7 Days", from: () => isoDaysAgo(7), to: () => isoDaysAgo(0) },
  { key: "30d", label: "Last 30 Days", from: () => isoDaysAgo(30), to: () => isoDaysAgo(0) },
  { key: "90d", label: "Last 90 Days", from: () => isoDaysAgo(90), to: () => isoDaysAgo(0) },
  { key: "custom", label: "Custom Range" },
];

export default {
  name: "FilterPopup",
  props: {
    // Full mapped dashboard data object (has one array per FILTER_GROUPS.dataKey).
    dashboardData: { type: Object, default: () => ({}) },
    // Current object type — groups with `appliesTo` only show for matching types.
    objectType: { type: String, default: "" },
  },
  emits: ["apply"],

  data() {
    return { text: FILTER_POPUP_TEXT, open: false, sel: {}, datePresets: DATE_PRESETS };
  },

  computed: {
    groups() {
      return FILTER_GROUPS.filter((g) => !g.appliesTo || g.appliesTo.includes(this.objectType)).map((g) => ({
        ...g,
       options: g.type === "chip" ? (g.staticOptions || (this.dashboardData[g.dataKey] || []).map((o) => ({ label: o.label || o.name, raw: o.raw }))) : [],
      }));
    },
    activeCount() {
      return this.groups.reduce((n, g) => {
        const v = this.sel[g.key];
        if (g.type === "chip") return n + (v ? v.length : 0);
        if (g.type === "date-range") return n + (v?.from || v?.to ? 1 : 0);
        return n + (v ? 1 : 0);
      }, 0);
    },
  },

  watch: {
    groups: { immediate: true, handler() { this.ensureSelShape(); } },
  },

  methods: {
    ensureSelShape() {
      const next = {};
      this.groups.forEach((g) => { next[g.key] = this.sel[g.key] ?? emptyValue(g.type); });
      this.sel = next;
    },
    reset() {
      const next = {};
      this.groups.forEach((g) => { next[g.key] = emptyValue(g.type); });
      this.sel = next;
    },
    // Rebuild internal chip/date selection from a restored saved view's facetRefines,
    // so the count + active state stay in sync with what's actually applied.
    restoreSelection(facetRefines) {
      this.reset();
      (facetRefines || []).forEach((f) => {
        const g = this.groups.find((g) => g.facetKey === f.key);
        if (!g) return;
        if (g.type === "date-range") {
          this.sel[g.key] = { preset: "custom", from: f.value || "", to: f.valueTo || "" };
        } else {
          const opt = g.options.find((o) => o.raw === f.value);
          if (opt) this.sel[g.key].push(opt);
        }
      });
    },
    applyPreset(key, presetKey) {
      if (this.sel[key].preset === presetKey) {
        this.sel[key] = { preset: "", from: "", to: "" };
        return;
      }
      const preset = DATE_PRESETS.find((p) => p.key === presetKey);
      this.sel[key] = {
        preset: presetKey,
        from: preset.from ? preset.from() : this.sel[key].from || "",
        to: preset.to ? preset.to() : this.sel[key].to || "",
      };
    },
    toggleChip(key, opt) {
      const arr = this.sel[key];
      const i = arr.findIndex((o) => o.raw === opt.raw);
      if (i > -1) arr.splice(i, 1);
      else arr.push(opt);
    },
    removeChip(label) {
      const g = this.groups.find((g) => label.startsWith(g.label + " = "));
      if (!g) return;
      if (g.type === "chip") {
        const optLabel = label.slice(g.label.length + 3);
        this.sel[g.key] = this.sel[g.key].filter((o) => o.label !== optLabel);
      } else {
        this.sel[g.key] = emptyValue(g.type);
      }
    },
    apply() {
      const chips = [];
      const facetRefines = [];
      this.groups.forEach((g) => {
        const v = this.sel[g.key];
        if (g.type === "chip") {
          v.forEach((o) => {
            chips.push(`${g.label} = ${o.label}`);
            facetRefines.push({ key: g.facetKey, value: o.raw });
          });
        } else if (g.type === "date-range") {
          if (v.from || v.to) {
            const label = v.from && v.to ? `${v.from} to ${v.to}` : v.from || v.to;
            chips.push(`${g.label} = ${label}`);
            facetRefines.push({ key: g.facetKey, value: v.from || "", valueTo: v.to || "" });
          }
        } else if (v) {
          chips.push(`${g.label} = ${v}`);
          facetRefines.push({ key: g.facetKey, value: v });
        }
      });
      this.$emit("apply", { chips, facetRefines });
      this.open = false;
    },
  },
};
</script>

<style scoped>
.filter-pill { display: inline-flex; align-items: center; gap: 4px; height: 28px; padding: 0 8px; border: 0; border-radius: var(--dw-radius-sm); background: transparent; font-family: inherit; font-size: var(--dw-fs-base); font-weight: var(--dw-fw-medium); color: var(--dw-primary); cursor: pointer; }
.filter-pill:hover { background: var(--dw-primary-soft); }
.fp-card { width: 340px; max-width: 90vw; max-height: 70vh; overflow-y: auto; background: var(--dw-surface); padding: var(--dw-sp-4); border: 1px solid var(--dw-border); border-radius: var(--dw-radius-lg); box-shadow: var(--dw-shadow-lg); }
.fp-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: var(--dw-sp-3); }
.fp-group { margin-bottom: var(--dw-sp-4); }
.fp-label { font-size: var(--dw-fs-sm); font-weight: var(--dw-fw-semibold); color: var(--dw-text-2); margin-bottom: var(--dw-sp-2); }
.fp-chips { display: flex; flex-wrap: wrap; gap: var(--dw-sp-2); }
.fp-chip { border: 1px solid var(--dw-border-strong); border-radius: var(--dw-radius-pill); padding: 4px 12px; font-size: var(--dw-fs-sm); cursor: pointer; color: var(--dw-text-2); background: var(--dw-surface); font-family: inherit; }
.fp-chip:hover { border-color: var(--dw-primary); }
.fp-chip.active { border-color: var(--dw-primary); color: var(--dw-primary); background: var(--dw-primary-soft); font-weight: var(--dw-fw-semibold); }
.fp-date-row { display: flex; align-items: center; gap: var(--dw-sp-2); }
.fp-date-input { flex: 1; min-width: 0; height: var(--dw-control-h); border: 1px solid var(--dw-border-strong); border-radius: var(--dw-radius); padding: 0 var(--dw-sp-2); font-size: var(--dw-fs-sm); color: var(--dw-text-2); font-family: inherit; }
.fp-date-sep { font-size: var(--dw-fs-sm); color: var(--dw-text-subtle); }
.fp-foot { position: sticky; bottom: calc(-1 * var(--dw-sp-4)); background: var(--dw-surface); padding-top: var(--dw-sp-2); }
.fp-foot .btn-primary { width: 100%; }
</style>
