<template>
  <div class="db-wrap">
    <div class="topbar">
      <div class="topbar-left">
        <span class="label">{{ text.typeLabel }}</span>
        <span class="type-pill" :title="`Object type: ${type}`">{{ type }}</span>
        <template v-if="currentDashboard">
          <span class="topbar-sep" aria-hidden="true" />
          <span class="db-name" :title="currentDashboard.description || currentDashboard.name">
            <v-icon icon="mdi-view-dashboard-outline" size="16" />{{ currentDashboard.name }}
          </span>
          <span v-if="isOwner" class="dw-badge dw-badge--primary">Owner</span>
          <span v-else class="dw-badge" title="Shared with you: you can use it and save your own copy">
            <v-icon icon="mdi-eye-outline" />Read only
          </span>
        </template>
        <FilterPopup ref="filterPopup" :dashboard-data="data" :object-type="type" @apply="onApplyFilters" />
      </div>
      <div class="topbar-right">
        <span class="refreshed">{{ text.refreshedPrefix }} {{ lastRefreshed }}</span>
        <button type="button" class="icon-btn" aria-label="Refresh dashboard" title="Refresh dashboard" :disabled="refreshing" @click="refresh">
          <v-icon icon="mdi-refresh" :class="{ spin: refreshing }" />
        </button>
        <button type="button" class="icon-btn" aria-label="View / layout settings" title="View / layout settings" @click="viewSettingsDialog = true">
          <v-icon icon="mdi-view-dashboard-outline" />
        </button>
        <button type="button" class="icon-btn" aria-label="Reset to default" title="Reset to default" @click="resetDialog = true">
          <v-icon icon="mdi-restore" />
        </button>
        <button type="button" class="btn-primary" title="Add a custom attribute chart" @click="addChartDialog = true">
          <v-icon icon="mdi-plus" /> {{ text.addChart }}
        </button>
        <button v-if="canShare && currentDashboard" type="button" class="btn-outline" title="Share this dashboard with other users" @click="shareOpen = true">
          <v-icon icon="mdi-share-variant-outline" /> Share
        </button>
        <button type="button" class="btn-outline" :title="saveTitle" @click="openSave">
          {{ saveLabel }}
        </button>
      </div>
    </div>

    <SaveDashboardDialog
      v-model="saveDialog.open"
      :mode="saveDialog.mode"
      :initial="currentDashboard ? { name: currentDashboard.name, description: currentDashboard.description } : {}"
      :ctx-options="store.ctxOptions"
      :default-ctx="currentCtx"
      :existing-names="ownedNames"
      :summary="saveSummary"
      :busy="saveDialog.busy"
      :error="saveDialog.error"
      @save="handleSaveDashboard"
    />
    <ShareDialog v-if="sharingAvailable && currentDashboard" v-model="shareOpen" :dashboard="currentDashboard" />
    <ConfirmDialog
      v-model="conflictOpen"
      title="This dashboard was changed by someone else"
      message="Saving now would overwrite their changes. Save your version as a copy instead, or reopen the dashboard to see the latest version."
      confirm-label="Save as a copy"
      icon="mdi-source-branch"
      @confirm="saveAsCopyAfterConflict"
    />

    <div class="chips-row" v-if="activeFilters.length && viewSettings.showFilterBar !== false" aria-label="Active filters">
      <span v-for="(f, i) in activeFilters" :key="f" class="dw-chip">
        {{ f }}
        <button type="button" class="dw-chip__remove" :aria-label="`Remove filter ${f}`" @click="removeFilter(i)">
          <v-icon icon="mdi-close" size="14" />
        </button>
      </span>
      <button type="button" class="btn-ghost btn-sm" @click="clearFilters">{{ text.clearAll }}</button>
    </div>

    <ResetConfirmDialog v-model="resetDialog" @confirm="resetToDefault" />
    <AddChartDialog v-model="addChartDialog" @add="handleAddChart" />
    <ViewSettingsDialog v-model="viewSettingsDialog" :settings="viewSettings" @apply="store.setViewSettings($event)" />

    <div class="content">
      <div class="main" :class="{ compact: viewSettings.compact }">
        <StateMessage v-if="loadingData && !data.total" loading :title="text.loadingTitle"
          :message="text.loadingMessage" />
        <StateMessage v-else-if="errorState" icon="mdi-power-plug-off-outline" tone="error"
          :title="text.errorTitle" :message="text.errorMessage" :action-label="text.retry"
          @action="refresh" />
        <StateMessage v-else-if="!data.total" icon="mdi-package-variant"
          :title="text.emptyTitle" :message="text.emptyMessage" :action-label="text.clearFilters"
          @action="clearFilters" />
        <template v-else>
          <KpiCards v-if="viewSettings.showKpis" :total="data.total" :kpis="data.kpis" :type="type" />
          <div class="panel-row" v-for="pair in chunkedCharts" :key="pair[0].id"
            :style="{ gridTemplateColumns: `repeat(${pair.length}, 1fr)` }">
            <ChartPanel v-for="c in pair" :key="c.id" :chart="c" @move="moveChart(c.id, $event)"
              @remove="removeChart(c.id)" @drill="openDrill" @refresh="refreshChart(c)" />
          </div>
        </template>
      </div>
      <DrillDownPanel v-if="drill.open" :drill="drill" @close="closeDrill" @page="goDrillPage" />
    </div>
  </div>
</template>

<script>
import KpiCards from "@/components/dashboard/KpiCards.vue";
import ChartPanel from "@/components/dashboard/ChartPanel.vue";
import AddChartDialog from "@/components/dashboard/AddChartDialog.vue";
import DrillDownPanel from "@/components/dashboard/DrillDownPanel.vue";
import ResetConfirmDialog from "@/components/dashboard/ResetConfirmDialog.vue";
import FilterPopup from "@/components/dashboard/FilterPopup.vue";
import ViewSettingsDialog from "@/components/dashboard/ViewSettingsDialog.vue";
import SaveDashboardDialog from "@/components/dashboard/SaveDashboardDialog.vue";
import ShareDialog from "@/components/dashboard/ShareDialog.vue";
import ConfirmDialog from "@/components/common/ConfirmDialog.vue";
import dashboardDocumentApi from "@/services/dashboardDocumentApi";
import sharingApi from "@/services/sharingApi";
import initApp from "@/utils/initApp";
import { userMessage, ERROR_CODES } from "@/services/apiError";
import { DEFAULT_VIEW_SETTINGS } from "@/utils/dashboardData";
import StateMessage from "@/components/common/StateMessage.vue";
import {
  DEFAULT_CHART_ORDER,
  FACET_KEY_BY_CHART,
  ATTRIBUTE_FACET_KEY,
  DATE_ATTRIBUTES,
} from "@/utils/dashboardData";
import {
  mapFederatedResponse,
  mapFacet,
  mapDateFacet,
} from "@/utils/dashboardMapper";
import { DASHBOARD_TEXT, ERROR_TEXT } from "@/utils/uiText";
import { logError } from "@/utils/logger";
import dashboardApi from "../services/dashboardApi.js";
import detailApi from "../services/detailApi.js";
import { useDashboardStore } from "@/store/dashboardStore";
import { toastBus } from "@/components/common/toastBus";
import externalApi from "@/services/externalApi";
import { mapExternalProjects, matchesDrill } from "@/utils/externalMapper";
export default {
  name: "DashboardView",
  components: {
    KpiCards,
    ChartPanel,
    AddChartDialog,
    DrillDownPanel,
    ResetConfirmDialog,
    FilterPopup,
    ViewSettingsDialog,
    SaveDashboardDialog,
    ShareDialog,
    ConfirmDialog,
    StateMessage,
  },

  props: {
    // { meta, state } from dashboardDocumentApi.open / save
    restoreDashboard: { type: Object, default: null },
  },
  emits: ["saved"],

  setup() {
    return { store: useDashboardStore() };
  },

  data() {
    return {
      text: DASHBOARD_TEXT,
      activeFilters: [],
      activeFacetRefines: [],
      resetDialog: false,
      addChartDialog: false,
      saveDialog: { open: false, mode: "create", busy: false, error: "" },
      shareOpen: false,
      restoring: false,
      conflictOpen: false,
      pendingSave: null,
      ownedNames: [],
      sharingAvailable: sharingApi.isAvailable(),
      canShare: false, // from the platform (checkaccess) for the open dashboard
      currentDashboard: null, // document metadata of the open dashboard
      viewSettingsDialog: false,
      refreshing: false,
      loadingData: false,
      errorState: false,
      lastRefreshed: "—",
      data: {
        total: 0,
        kpis: [],
        line: [],
        lineCategories: [],
        owners: [],
        policies: [],
        results: [],
      },
      order: [...DEFAULT_CHART_ORDER],
      customCharts: {},
      nextChartId: 1,
      drill: {
        open: false,
        loading: false,
        filterLabel: "",
        total: 0,
        items: [],
        page: 1,
        chartId: null,
        raw: null,
        nextStart: null,
      },
    };
  },

  computed: {
    isOwner() {
      // Owner, or 3DSpace reports modify access on the document (hasModifyAccess).
      return !this.currentDashboard || this.currentDashboard.access === "owner" || this.currentDashboard.canModify === true;
    },
    saveLabel() {
      if (!this.currentDashboard) return "Save Dashboard";
      return this.isOwner ? "Save Dashboard" : "Save a Copy";
    },
    saveTitle() {
      if (!this.currentDashboard) return "Save this dashboard as a 3DEXPERIENCE Document";
      return this.isOwner ? "Save changes to this dashboard" : "This dashboard is shared with you. Save your own copy to keep changes.";
    },
    currentCtx() {
      return initApp.getCTX() || "";
    },
    saveSummary() {
      const custom = Object.keys(this.customCharts).length;
      return [
        `Object type · ${this.type}`,
        `${this.order.length} charts and their order`,
        `${this.activeFilters.length} active filters`,
        this.store.customForm ? "Custom query criteria" : "Layout settings",
        ...(custom ? [`${custom} custom attribute charts`] : []),
      ];
    },
    type() {
      return this.store.type;
    },
    typeOptions() {
      return this.store.getTypeOptions;
    },
    viewSettings() {
      return this.store.viewSettings;
    },
    defaultCharts() {
      return {
        maturity: {
          id: "maturity",
          kind: "donut",
          title: "Maturity State",
          categories: this.data.kpis.map((k) => k.label),
          rawCategories: this.data.kpis.map((k) => k.raw),
          series: this.data.kpis.map((k) => k.value),
          pct: this.data.kpis.map((k) => k.pct),
          colors: this.data.kpis.map((k) => k.color),
        },
        created: {
          id: "created",
          kind: "line",
          title: "Created Per Month",
          categories: this.data.lineCategories,
          rawCategories: this.data.lineRaw,
          series: this.data.line,
        },
        owners: {
          id: "owners",
          kind: "bar-h",
          title: "Top 10 Owners",
          categories: this.data.owners.map((o) => o.name),
          rawCategories: this.data.owners.map((o) => o.raw),
          series: this.data.owners.map((o) => o.value),
        },
        policy: {
          id: "policy",
          kind: "donut",
          title: "Policy Distribution",
          categories: this.data.policies.map((p) => p.label),
          rawCategories: this.data.policies.map((p) => p.raw),
          series: this.data.policies.map((p) => p.value),
          pct: this.data.policies.map((p) => p.pct),
          colors: this.data.policies.map((p) => p.color),
        },
      };
    },
    allCharts() {
      const lookup = { ...this.defaultCharts, ...this.customCharts };
      return this.order.map((id) => lookup[id]).filter(Boolean);
    },
    chunkedCharts() {
      const size = Math.max(1, this.viewSettings.columns || 2);
      const pairs = [];
      for (let i = 0; i < this.allCharts.length; i += size)
        pairs.push(this.allCharts.slice(i, i + size));
      return pairs;
    },
  },

  watch: {
    type() {
      // Restoring a saved dashboard changes the type and loads data itself.
      if (!this.restoring) this.loadData();
    },
    // Ask the platform whether the current user may share the open dashboard.
    "currentDashboard.id": {
      immediate: true,
      async handler(id) {
        this.canShare = false;
        if (!id || !this.sharingAvailable) return;
        const allowed = await sharingApi.canShare(id).catch(() => false);
        if (this.currentDashboard?.id === id) this.canShare = allowed;
      },
    },
  },

  async mounted() {
    if (this.restoreDashboard) {
      this.restoring = true;
      this.applyRestoredDashboard(this.restoreDashboard);
      await this.$nextTick();
      this.restoring = false;
    }
    await this.loadData();
    if (this.restoreDashboard)
      this.$refs.filterPopup?.restoreSelection(this.activeFacetRefines);
  },

  methods: {
    // view = { meta, state }; state comes from utils/dashboardSerializer.parse
    applyRestoredDashboard(view) {
      const st = view.state || {};
      this.currentDashboard = view.meta || null;
      this.store.setType(st.type);
      this.store.setSource(st.source || "3dx");
      this.store.setCustomForm(st.customForm || null);
      if (st.viewSettings) this.store.setViewSettings({ ...DEFAULT_VIEW_SETTINGS, ...st.viewSettings });
      this.activeFilters = st.chips || [];
      this.activeFacetRefines = st.facetRefines || [];
      this.order = st.order && st.order.length ? st.order : [...DEFAULT_CHART_ORDER];
      this.customCharts = st.customCharts || {};
    },

    currentState() {
      return {
        type: this.type,
        source: this.store.source,
        customForm: this.store.customForm,
        chips: this.activeFilters,
        facetRefines: this.activeFacetRefines,
        order: this.order,
        customCharts: this.customCharts,
        viewSettings: this.viewSettings,
      };
    },

    async openSave() {
      const mode = !this.currentDashboard ? "create" : this.isOwner ? "update" : "copy";
      this.saveDialog = { open: true, mode, busy: false, error: "" };
      // Names of the user's own dashboards, for the duplicate-name check.
      try {
        const list = await dashboardDocumentApi.list();
        this.ownedNames = list.filter((d) => d.access === "owner").map((d) => d.name);
      } catch (e) {
        this.ownedNames = [];
      }
    },

    async handleSaveDashboard(form) {
      this.saveDialog.busy = true;
      this.saveDialog.error = "";
      const state = this.currentState();
      try {
        const meta =
          this.saveDialog.mode === "update"
            ? await dashboardDocumentApi.update(this.currentDashboard, { ...form, state })
            : await dashboardDocumentApi.create({ ...form, state });
        this.currentDashboard = meta;
        this.saveDialog.open = false;
        toastBus.emit(this.saveDialog.mode === "update" ? "Dashboard updated." : `“${meta.name}” was saved.`, "success");
        this.$emit("saved", { meta, state });
      } catch (e) {
        if (e?.code === ERROR_CODES.CONFLICT) {
          this.saveDialog.open = false;
          this.pendingSave = form;
          this.conflictOpen = true;
        } else {
          this.saveDialog.error = userMessage(e, ERROR_TEXT.saveDashboard);
        }
      } finally {
        this.saveDialog.busy = false;
      }
    },

    saveAsCopyAfterConflict() {
      this.conflictOpen = false;
      this.saveDialog = { open: true, mode: "copy", busy: false, error: "" };
    },

    async loadData() {
      this.loadingData = true;
      this.errorState = false;
      try {
        if (this.store.source === "external") {
          this.data = mapExternalProjects(await externalApi.getProjects());
        } else {
          const json = this.activeFacetRefines.length
            ? await dashboardApi.fetchFilteredDashboardData(this.type, this.activeFacetRefines)
            : await dashboardApi.fetchDashboardData(this.type);
          this.data = mapFederatedResponse(json);
        }
        this.lastRefreshed = new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
        this.refreshAllCustomCharts();
      } catch (e) {
        // shown on the page (StateMessage with Retry); no toast, to avoid a double message
        logError("dashboard", "Loading dashboard data failed:", e);
        this.errorState = true;
      } finally {
        this.loadingData = false;
      }
    },

    refresh() {
      this.refreshing = true;
      this.loadData().finally(() => {
        this.refreshing = false;
      });
    },

    refreshAllCustomCharts() {
      const updated = {};
      for (const c of Object.values(this.customCharts)) {
        updated[c.id] = this.buildChartFromFacet(
          c.id,
          c.kind,
          c.title,
          c.xAttr
        );
      }
      this.customCharts = { ...this.customCharts, ...updated };
    },

    refreshChart(c) {
      if (FACET_KEY_BY_CHART[c.id]) {
        this.loadData();
      } else {
        this.customCharts = {
          ...this.customCharts,
          [c.id]: this.buildChartFromFacet(c.id, c.kind, c.title, c.xAttr),
        };
      }
    },

    buildChartFromFacet(id, kind, title, xAttr) {
      const facetKey = ATTRIBUTE_FACET_KEY[xAttr];
      const rows = !facetKey
        ? []
        : DATE_ATTRIBUTES.includes(xAttr)
          ? mapDateFacet(this.data.facets || [], facetKey)
          : mapFacet(this.data.facets || [], facetKey);
      const categories = rows.length ? rows.map((r) => r.label) : ["No data"];
      const series = rows.length ? rows.map((r) => r.value) : [0];
      return { id, kind, title, xAttr, categories, series };
    },

    handleAddChart(form) {
      const id = "c" + Date.now() + "_" + this.nextChartId++;
      const title = `${form.xAttr}`;
      this.customCharts = {
        ...this.customCharts,
        [id]: this.buildChartFromFacet(id, form.chartType, title, form.xAttr),
      };
      this.order = [...this.order, id];
    },

    removeChart(id) {
      this.order = this.order.filter((o) => o !== id);
      if (this.customCharts[id]) {
        const cc = { ...this.customCharts };
        delete cc[id];
        this.customCharts = cc;
      }
    },

    moveChart(id, dir) {
      const i = this.order.indexOf(id);
      const j = i + dir;
      if (i < 0 || j < 0 || j >= this.order.length) return;
      const arr = [...this.order];
      [arr[i], arr[j]] = [arr[j], arr[i]];
      this.order = arr;
    },

    resetToDefault() {
      this.order = [...DEFAULT_CHART_ORDER];
      this.customCharts = {};
      this.activeFilters = [];
      this.activeFacetRefines = [];
      this.errorState = false;
      this.$refs.filterPopup?.reset();
      this.loadData();
    },

    onApplyFilters({ chips, facetRefines }) {
      this.activeFilters = chips;
      this.activeFacetRefines = facetRefines;
      this.loadData();
    },

    removeFilter(i) {
      this.$refs.filterPopup?.removeChip(this.activeFilters[i]);
      this.activeFacetRefines.splice(i, 1);
      this.activeFilters.splice(i, 1);
      this.loadData();
    },

    clearFilters() {
      this.activeFilters = [];
      this.activeFacetRefines = [];
      this.$refs.filterPopup?.reset();
      this.loadData();
    },

    resolveFacetKey(chartId) {
      if (FACET_KEY_BY_CHART[chartId]) return FACET_KEY_BY_CHART[chartId];
      const chart = this.allCharts.find((c) => c.id === chartId);
      const attr = chart?.xAttr || chart?.title;
      return attr ? ATTRIBUTE_FACET_KEY[attr] : null;
    },

    async runDrillQuery() {
      this.drill.loading = true;
      try {
        if (this.store.source === "external") {
          const rows = (this.data.results || []).filter((r) =>
            matchesDrill(r, this.drill.raw),
          );
          this.drill.items = rows;
          this.drill.total = rows.length;
          this.drill.nextStart = null;
          return;
        }
        const json = await dashboardApi.fetchFacetDrilldown(
          this.type,
          this.resolveFacetKey(this.drill.chartId),
          this.drill.raw,
          10,
          this.drill.nextStart,
          this.activeFacetRefines
        );

        const mapped = mapFederatedResponse(json);
        this.drill.items = mapped.results;
        if (detailApi.hasDetailApi(this.type)) {
          this.drill.items = await Promise.all(
            this.drill.items.map(async (row) => {
              try {
                const detail = await detailApi.fetchDetail(
                  this.type,
                  row.resourceid
                );
                const attrs = this.store.type == "Project" || this.store.type == "Program" || this.store.type == "Document" || this.store.type == "Task" ? detail?.data?.[0]?.dataelements : this.store.type == "Engineering" ? detail?.member?.[0] : {};
                const due = attrs.dueDate ? new Date(attrs.dueDate) : null;
                const delayed =
                  due && !attrs.actualFinishDate && due < new Date()
                    ? "Yes"
                    : "No";

                return {
                  ...row,
                  ...attrs,
                  delayed,
                };
              } catch (e) {
                return row;
              }
            })
          );
        }
        this.drill.total = mapped.total;
        // Save cursor returned by server
        this.drill.nextStart = json?.infos?.next_start || null;
      } catch (e) {
        logError("dashboard", "Drill-down query failed:", e);
        toastBus.emit(ERROR_TEXT.loadDrillDown, "error");
        this.drill.items = [];
        this.drill.total = 0;
      } finally {
        this.drill.loading = false;
      }
    },

    openDrill({ chartId, label, raw }) {
      this.drill = {
        open: true,
        loading: true,
        filterLabel: label,
        total: 0,
        items: [],
        page: 1,
        chartId,
        raw,
      };
      this.$nextTick(() =>
        setTimeout(() => window.dispatchEvent(new Event("resize")), 50)
      );
      if (this.resolveFacetKey(chartId)) {
        this.runDrillQuery();
      } else {
        console.warn(
          "No facet key resolved for chart:",
          chartId,
          "— skipping drilldown API call."
        );
        this.drill.loading = false;
        this.drill.items = [];
        this.drill.total = 0;
      }
    },

    goDrillPage(p) {
      if (p < 1) return;

      this.drill.page = p;

      const token = this.drill.nextStart
        ? this.drill.nextStart.split(" ")[3]
        : "";

      const offset = (p - 1) * 10;
      const pageIndex = p - 1;

      this.drill.nextStart =
        p === 1 ? null : `${offset} 0 ${pageIndex} ${token}`;

      this.runDrillQuery();
    },

    closeDrill() {
      this.drill.open = false;
      this.$nextTick(() =>
        setTimeout(() => window.dispatchEvent(new Event("resize")), 50)
      );
    },
  },
};
</script>

<style scoped>
.db-wrap {
  padding: 16px 20px;
  box-sizing: border-box;
}

.topbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 12px;
  flex-wrap: wrap;
  gap: 8px;
}

.topbar-left {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  min-width: 0;
}

.label {
  font-size: var(--dw-fs-base);
  color: var(--dw-text-muted);
}

.type-pill {
  display: inline-flex;
  align-items: center;
  height: 28px;
  border: 1px solid var(--dw-primary-border);
  border-radius: var(--dw-radius-sm);
  padding: 0 10px;
  font-size: var(--dw-fs-base);
  font-weight: var(--dw-fw-semibold);
  color: var(--dw-primary);
  background: var(--dw-primary-soft);
}

.topbar-sep {
  width: 1px;
  height: 20px;
  background: var(--dw-border-strong);
}

.db-name {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  max-width: 320px;
  font-size: var(--dw-fs-md);
  font-weight: var(--dw-fw-semibold);
  color: var(--dw-text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.db-name .v-icon {
  color: var(--dw-primary);
}

.topbar-right {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
