<template>
  <DwDialog
    :model-value="modelValue"
    :title="titleText"
    :subtitle="subtitleText"
    icon="mdi-content-save-outline"
    :busy="busy"
    max-width="540"
    @update:model-value="$emit('update:modelValue', $event)"
  >
    <form id="dw-save-form" class="sv-form" novalidate @submit.prevent="submit">
      <div class="dw-field">
        <label class="dw-label" for="sv-name">Dashboard name <span class="dw-required">*</span></label>
        <v-text-field
          id="sv-name"
          v-model="name"
          placeholder="e.g. Q4 change readiness"
          hide-details="auto"
          maxlength="120"
          counter="120"
          :error-messages="touched ? nameError : ''"
          :disabled="busy"
          autofocus
          @blur="touched = true"
        />
      </div>

      <div class="dw-field">
        <label class="dw-label" for="sv-desc">Description <span class="dw-hint">(optional)</span></label>
        <v-textarea id="sv-desc" v-model="description" rows="3" auto-grow maxlength="400" counter="400" hide-details="auto" :disabled="busy" />
      </div>

      <div v-if="showSpace" class="dw-field">
        <label class="dw-label" for="sv-space">Collaborative space <span class="dw-required">*</span></label>
        <v-select
          id="sv-space"
          v-model="ctx"
          :items="ctxOptions"
          item-title="label"
          item-value="value"
          prepend-inner-icon="mdi-folder-account-outline"
          hide-details="auto"
          :error-messages="touched && !ctx ? 'Choose where the dashboard is stored.' : ''"
          :disabled="busy"
        />
        <span class="dw-hint">The dashboard is stored as a 3DEXPERIENCE Document in this space. People with access to the space can find it according to their roles.</span>
      </div>

      <div class="sv-summary">
        <div class="sv-summary__title">What gets saved</div>
        <ul>
          <li v-for="item in summary" :key="item"><v-icon icon="mdi-check" />{{ item }}</li>
          <li class="sv-summary__muted"><v-icon icon="mdi-shield-lock-outline" />No passwords, tokens or data rows</li>
        </ul>
      </div>

      <div v-if="error" class="dw-alert dw-alert--error" role="alert">
        <v-icon icon="mdi-alert-circle-outline" size="18" />
        <span>{{ error }}</span>
      </div>
    </form>

    <template #footer>
      <button type="button" class="btn-outline" :disabled="busy" @click="$emit('update:modelValue', false)">Cancel</button>
      <button type="submit" form="dw-save-form" class="btn-primary" :class="{ 'btn-busy': busy }" :disabled="busy || !!nameError">
        <span v-if="busy" class="dw-spinner" aria-hidden="true" />
        <v-icon v-else icon="mdi-content-save-outline" />
        {{ busy ? "Saving…" : confirmText }}
      </button>
    </template>
  </DwDialog>
</template>

<script>
import DwDialog from "@/components/common/DwDialog.vue";

// Save / update / save-a-copy dialog for dashboard documents (FR-06, FR-10, §9).
// The parent performs the API call; the dialog stays open with a busy state until the
// platform answers, and shows the error in place if the save fails.
export default {
  name: "SaveDashboardDialog",
  components: { DwDialog },
  props: {
    modelValue: Boolean,
    mode: { type: String, default: "create" }, // create | update | copy
    initial: { type: Object, default: () => ({}) },
    ctxOptions: { type: Array, default: () => [] },
    defaultCtx: { type: String, default: "" },
    existingNames: { type: Array, default: () => [] },
    summary: { type: Array, default: () => [] },
    busy: { type: Boolean, default: false },
    error: { type: String, default: "" },
  },
  emits: ["update:modelValue", "save"],
  data() {
    return { name: "", description: "", ctx: "", touched: false };
  },
  computed: {
    titleText() {
      return { create: "Save Dashboard", update: "Update Dashboard", copy: "Save a Copy" }[this.mode] || "Save Dashboard";
    },
    subtitleText() {
      if (this.mode === "update") return "Changes are saved to the existing 3DEXPERIENCE Document.";
      if (this.mode === "copy") return "You can't change this dashboard, but you can save your own copy.";
      return "Saved as a 3DEXPERIENCE Document that you own.";
    },
    confirmText() {
      return this.mode === "update" ? "Update Dashboard" : "Save Dashboard";
    },
    showSpace() {
      return this.mode !== "update" && this.ctxOptions.length > 0;
    },
    nameError() {
      const n = this.name.trim();
      if (!n) return "Enter a name.";
      if (n.length < 3) return "Use at least 3 characters.";
      if (/[<>]/.test(n)) return "The name can't contain < or >.";
      const original = (this.initial.name || "").trim().toLowerCase();
      const taken = this.existingNames.some((x) => x.trim().toLowerCase() === n.toLowerCase());
      if (taken && (this.mode !== "update" || n.toLowerCase() !== original)) {
        return "You already have a dashboard with this name.";
      }
      return "";
    },
  },
  watch: {
    modelValue(open) {
      if (!open) return;
      this.touched = false;
      this.name = this.mode === "copy" && this.initial.name ? `Copy of ${this.initial.name}` : this.initial.name || "";
      this.description = this.initial.description || "";
      this.ctx = this.defaultCtx || this.ctxOptions[0]?.value || "";
    },
  },
  methods: {
    submit() {
      this.touched = true;
      if (this.nameError || (this.showSpace && !this.ctx)) return;
      this.$emit("save", {
        name: this.name.trim(),
        description: this.description.trim(),
        // same "ctx::Role.Org.Space" format the widget already sends as SecurityContext
        ctx: this.showSpace ? this.ctx : "",
      });
    },
  },
};
</script>

<style scoped>
.sv-form {
  display: flex;
  flex-direction: column;
  gap: var(--dw-sp-4);
}
.sv-summary {
  border: 1px solid var(--dw-border);
  border-radius: var(--dw-radius);
  background: var(--dw-surface-alt);
  padding: var(--dw-sp-3) var(--dw-sp-4);
}
.sv-summary__title {
  font-size: var(--dw-fs-sm);
  font-weight: var(--dw-fw-semibold);
  color: var(--dw-text-2);
  margin-bottom: 6px;
}
.sv-summary ul {
  list-style: none;
  padding: 0;
  margin: 0;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 4px 16px;
  font-size: var(--dw-fs-sm);
  color: var(--dw-text-2);
}
.sv-summary li {
  display: flex;
  align-items: center;
  gap: 6px;
}
.sv-summary li .v-icon {
  font-size: 15px !important;
  color: var(--dw-success);
}
.sv-summary__muted,
.sv-summary__muted .v-icon {
  color: var(--dw-text-muted) !important;
}
</style>
