import http from "./httpClient";
import { EXTERNAL } from "@/config/platformConfig";

// Object-type configuration service (FR-02). Its URL is deployment-specific and is set
// with VUE_APP_TYPE_CONFIG_URL. When it is not set, or the call fails, the store uses
// its built-in fallback list.
class TypeConfigApi {
  isConfigured() {
    return !!EXTERNAL.typeConfigUrl;
  }

  getTypeConfig() {
    if (!this.isConfigured()) return Promise.resolve(null);
    return http.get(EXTERNAL.typeConfigUrl, { credentials: "omit" });
  }
}

export default new TypeConfigApi();
