<template>
  <div class="sv-wrap">
    <div class="sv-card">
    <div class="sv-head">
      <div>
        <div class="sv-title">Saved Dashboards</div>
        <div class="sv-sub">Dashboards stored as 3DEXPERIENCE Documents that you own or that have been shared with you</div>
      </div>
      <div class="sv-head-actions">
        <button type="button" class="icon-btn icon-btn--bordered" aria-label="Refresh list" title="Refresh" :disabled="loading" @click="load">
          <v-icon icon="mdi-refresh" :class="{ 'is-spinning': loading }" />
        </button>
        <button type="button" class="btn-primary" @click="$emit('new')">
          <v-icon icon="mdi-plus" /> New Dashboard
        </button>
      </div>
    </div>

    <div class="sv-tabs" role="tablist" aria-label="Filter dashboards by ownership">
      <button
        v-for="t in tabs"
        :key="t.id"
        type="button"
        role="tab"
        class="sv-tab"
        :class="{ 'is-active': tab === t.id }"
        :aria-selected="tab === t.id ? 'true' : 'false'"
        @click="tab = t.id"
      >
        {{ t.label }} <span class="dw-count">{{ t.count }}</span>
      </button>
    </div>

    <div class="dw-toolbar">
      <v-text-field
        v-model="search"
        class="sv-search"
        prepend-inner-icon="mdi-magnify"
        placeholder="Search by name or description"
        hide-details
        clearable
        density="compact"
        aria-label="Search dashboards"
      />
      <v-select v-model="sort" :items="sortOptions" density="compact" hide-details class="sv-sort" aria-label="Sort dashboards" />
      <span class="dw-spacer" />
      <span v-if="!loading && !error" class="dw-caption">{{ filtered.length }} of {{ items.length }}</span>
    </div>

    <div v-if="!sharingAvailable && !loading && !error" class="dw-alert">
      <v-icon icon="mdi-information-outline" size="18" />
      <span>
        Dashboards are visible to people with access to the collaborative space they're saved in.
        Sharing with individual users needs to be enabled by your platform administrator.
      </span>
    </div>

    <div class="table-wrapper">
      <table class="saved-table">
        <thead>
          <tr>
            <th scope="col">Dashboard</th>
            <th scope="col" class="col-owner">Owner</th>
            <th scope="col">Your access</th>
            <th scope="col" class="col-modified">Modified</th>
            <th scope="col" class="col-actions"><span class="sr-only">Actions</span></th>
          </tr>
        </thead>
        <tbody v-if="loading">
          <tr v-for="n in 5" :key="'sk' + n">
            <td><div class="dw-skeleton" style="height: 14px; width: 60%" /><div class="dw-skeleton" style="height: 10px; width: 40%; margin-top: 6px" /></td>
            <td class="col-owner"><div class="dw-skeleton" style="height: 12px; width: 70%" /></td>
            <td><div class="dw-skeleton" style="height: 20px; width: 70px" /></td>
            <td class="col-modified"><div class="dw-skeleton" style="height: 12px; width: 80px" /></td>
            <td />
          </tr>
        </tbody>
        <tbody v-else-if="!error && filtered.length">
          <tr v-for="item in filtered" :key="item.id" class="sv-row">
            <td>
              <button type="button" class="sv-name" :disabled="!!opening" :title="item.name" @click="open(item)">
                <span class="sv-name__icon"><v-icon icon="mdi-view-dashboard-outline" /></span>
                <span class="sv-name__text">
                  <span class="sv-name__title">{{ item.name }}</span>
                  <span class="sv-name__desc">{{ item.description || "No description" }}</span>
                </span>
                <span v-if="opening === item.id" class="dw-spinner sv-name__spin" aria-label="Opening" />
              </button>
            </td>
            <td class="col-owner">
              <span class="sv-owner">{{ item.access === "owner" ? "You" : item.ownerName || item.owner || "—" }}</span>
            </td>
            <td>
              <span v-if="item.access === 'owner'" class="dw-badge dw-badge--primary"><v-icon icon="mdi-account-check-outline" />Owner</span>
              <span v-else class="dw-badge" title="Shared with you. Save a copy to make your own changes."><v-icon icon="mdi-account-multiple-outline" />Shared with you</span>
            </td>
            <td class="col-modified dw-caption">{{ formatDate(item.modified) }}</td>
            <td class="col-actions">
              <v-menu location="bottom end">
                <template #activator="{ props }">
                  <button type="button" class="icon-btn" v-bind="props" :aria-label="`Actions for ${item.name}`">
                    <v-icon icon="mdi-dots-horizontal" />
                  </button>
                </template>
                <v-list density="compact" class="sv-menu">
                  <v-list-item prepend-icon="mdi-open-in-app" title="Open" @click="open(item)" />
                  <v-list-item v-if="sharingAvailable && (item.access === 'owner' || item.canModify)" prepend-icon="mdi-share-variant-outline" title="Share…" @click="openShare(item)" />
                  <v-list-item v-if="item.access === 'owner'" prepend-icon="mdi-pencil-outline" title="Rename…" @click="openRename(item)" />
                  <v-list-item prepend-icon="mdi-content-copy" title="Save a copy…" @click="openCopy(item)" />
                  <template v-if="item.access === 'owner'">
                    <v-divider />
                    <v-list-item prepend-icon="mdi-delete-outline" title="Delete…" class="sv-menu__danger" @click="askDelete(item)" />
                  </template>
                </v-list>
              </v-menu>
            </td>
          </tr>
        </tbody>
      </table>

      <StateMessage
        v-if="!loading && error"
        tone="error"
        icon="mdi-power-plug-off-outline"
        :title="errorText.loadSavedDashboardsTitle"
        :message="error"
        action-label="Try again"
        @action="load"
      />
      <StateMessage
        v-else-if="!loading && !items.length"
        icon="mdi-bookmark-outline"
        title="No saved dashboards yet"
        message="Open a dashboard, then use Save to store it as a 3DEXPERIENCE Document."
        action-label="Create a dashboard"
        @action="$emit('new')"
      />
      <StateMessage
        v-else-if="!loading && !filtered.length"
        icon="mdi-filter-off-outline"
        title="No dashboards match"
        :message="tab === 'shared' ? 'Nothing has been shared with you yet.' : 'Try another search term or tab.'"
      />
    </div>
    <p v-if="truncated" class="dw-caption">Only the {{ items.length }} most recently modified dashboards are listed.</p>
    </div>

    <SaveDashboardDialog
      v-model="dialog.open"
      :mode="dialog.mode"
      :initial="dialog.item || {}"
      :ctx-options="store.ctxOptions"
      :default-ctx="currentCtx"
      :existing-names="ownedNames"
      :summary="['Same charts, filters and layout']"
      :busy="dialog.busy"
      :error="dialog.error"
      @save="onDialogSave"
    />
    <ConfirmDialog
      v-model="del.open"
      danger
      title="Delete Dashboard?"
      :message="`“${del.item?.name}” will be permanently deleted from 3DEXPERIENCE for you and everyone it's shared with.`"
      confirm-label="Delete"
      busy-label="Deleting…"
      :busy="del.busy"
      @confirm="confirmDelete"
    />
    <ShareDialog v-if="sharingAvailable" v-model="share.open" :dashboard="share.item" @changed="load" />
  </div>
</template>

<script>
import StateMessage from "@/components/common/StateMessage.vue";
import ConfirmDialog from "@/components/common/ConfirmDialog.vue";
import SaveDashboardDialog from "@/components/dashboard/SaveDashboardDialog.vue";
import ShareDialog from "@/components/dashboard/ShareDialog.vue";
import dashboardDocumentApi from "@/services/dashboardDocumentApi";
import sharingApi from "@/services/sharingApi";
import initApp from "@/utils/initApp";
import { userMessage, ERROR_CODES } from "@/services/apiError";
import { useDashboardStore } from "@/store/dashboardStore.js";
import { toastBus } from "@/components/common/toastBus";
import { formatDate } from "@/utils/format";
import { ERROR_TEXT } from "@/utils/uiText";

// Saved dashboards (FR-08..FR-13): lists dashboard documents returned by the platform
// as accessible to the current user. Owner-only actions are hidden for shared items;
// the platform still enforces access on every call.
export default {
  name: "SavedDashboardsView",
  components: { StateMessage, ConfirmDialog, SaveDashboardDialog, ShareDialog },
  emits: ["open", "new"],
  setup() {
    return { store: useDashboardStore() };
  },
  data() {
    return {
      errorText: ERROR_TEXT,
      items: [],
      truncated: false,
      loading: false,
      error: "",
      tab: "all",
      search: "",
      sort: "modified",
      sortOptions: [
        { title: "Last modified", value: "modified" },
        { title: "Name (A–Z)", value: "name" },
      ],
      opening: null,
      dialog: { open: false, mode: "update", item: null, busy: false, error: "" },
      del: { open: false, item: null, busy: false },
      share: { open: false, item: null },
      sharingAvailable: sharingApi.isAvailable(),
    };
  },
  computed: {
    owned() {
      return this.items.filter((i) => i.access === "owner");
    },
    ownedNames() {
      return this.owned.map((i) => i.name);
    },
    currentCtx() {
      return initApp.getCTX() || "";
    },
    tabs() {
      return [
        { id: "all", label: "All", count: this.items.length },
        { id: "owned", label: "Owned by me", count: this.owned.length },
        { id: "shared", label: "Shared with me", count: this.items.length - this.owned.length },
      ];
    },
    filtered() {
      const q = (this.search || "").trim().toLowerCase();
      const list = this.items.filter((i) => {
        if (this.tab === "owned" && i.access !== "owner") return false;
        if (this.tab === "shared" && i.access === "owner") return false;
        return !q || i.name.toLowerCase().includes(q) || i.description.toLowerCase().includes(q);
      });
      return this.sort === "name"
        ? [...list].sort((a, b) => a.name.localeCompare(b.name))
        : list;
    },
  },
  created() {
    this.load();
  },
  methods: {
    formatDate,
    async load() {
      this.loading = true;
      this.error = "";
      try {
        const list = await dashboardDocumentApi.list();
        this.items = list;
        this.truncated = !!list.truncated;
      } catch (e) {
        this.error = userMessage(e, "Check your connection and try again.");
      } finally {
        this.loading = false;
      }
    },
    async open(item) {
      if (this.opening) return;
      this.opening = item.id;
      try {
        const view = await dashboardDocumentApi.open(item.id);
        this.$emit("open", view);
      } catch (e) {
        toastBus.emit(userMessage(e, ERROR_TEXT.openDashboard), "error");
        // Access revoked or document deleted (AC-06): refresh what the platform returns.
        if ([ERROR_CODES.NOT_FOUND, ERROR_CODES.FORBIDDEN].includes(e?.code)) this.load();
      } finally {
        this.opening = null;
      }
    },
    openRename(item) {
      this.dialog = { open: true, mode: "update", item, busy: false, error: "" };
    },
    openCopy(item) {
      this.dialog = { open: true, mode: "copy", item, busy: false, error: "" };
    },
    openShare(item) {
      this.share = { open: true, item };
    },
    async onDialogSave({ name, description, ctx }) {
      const { item, mode } = this.dialog;
      this.dialog.busy = true;
      this.dialog.error = "";
      try {
        if (mode === "copy") {
          await dashboardDocumentApi.duplicate(item, { name, ctx });
          toastBus.emit(`“${name}” was saved as your own copy.`, "success");
        } else {
          // List metadata comes from the search index, so no timestamp conflict check here.
          await dashboardDocumentApi.rename({ ...item, modified: "" }, { name, description });
          toastBus.emit("Dashboard details updated.", "success");
        }
        this.dialog.open = false;
        await this.load();
      } catch (e) {
        this.dialog.error = userMessage(e, ERROR_TEXT.updateDashboardDetails);
      } finally {
        this.dialog.busy = false;
      }
    },
    askDelete(item) {
      this.del = { open: true, item, busy: false };
    },
    async confirmDelete() {
      this.del.busy = true;
      try {
        await dashboardDocumentApi.remove(this.del.item);
        toastBus.emit(`“${this.del.item.name}” was deleted.`, "success");
        this.items = this.items.filter((i) => i.id !== this.del.item.id);
        this.del.open = false;
      } catch (e) {
        toastBus.emit(userMessage(e, ERROR_TEXT.deleteDashboard), "error");
      } finally {
        this.del.busy = false;
      }
    },
  },
};
</script>

<style scoped>
.sv-wrap {
  padding: 24px;
  min-height: 100%;
  box-sizing: border-box;
}

.sv-card {
  background: var(--dw-surface);
  border: 1px solid var(--dw-border);
  border-radius: var(--dw-radius-lg);
  box-shadow: var(--dw-shadow-sm);
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.sv-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}

.sv-title {
  font-size: var(--dw-fs-xl);
  font-weight: var(--dw-fw-semibold);
  color: var(--dw-text);
}

.sv-sub {
  margin-top: 4px;
  color: var(--dw-text-muted);
  font-size: var(--dw-fs-base);
}

.sv-head-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.table-wrapper {
  overflow-x: auto;
}

.saved-table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0 8px;
  font-size: var(--dw-fs-base);
}

.saved-table thead th {
  background: var(--dw-surface-alt);
  color: var(--dw-text-muted);
  text-align: left;
  padding: 10px 16px;
  font-size: var(--dw-fs-xs);
  font-weight: var(--dw-fw-semibold);
  letter-spacing: 0.04em;
  text-transform: uppercase;
  white-space: nowrap;
}

.saved-table tbody tr {
  background: var(--dw-surface);
}

.saved-table td {
  padding: 14px 16px;
  border-top: 1px solid var(--dw-border);
  border-bottom: 1px solid var(--dw-border);
  vertical-align: middle;
  transition: background var(--dw-transition);
}

.saved-table td:first-child {
  border-left: 1px solid var(--dw-border);
  border-radius: var(--dw-radius-lg) 0 0 var(--dw-radius-lg);
}

.saved-table td:last-child {
  border-right: 1px solid var(--dw-border);
  border-radius: 0 var(--dw-radius-lg) var(--dw-radius-lg) 0;
}

.saved-table tbody tr:hover td {
  background: var(--dw-surface-alt);
}

.sv-tabs {
  display: flex;
  gap: var(--dw-sp-1);
  border-bottom: 1px solid var(--dw-border);
}
.sv-tab {
  display: inline-flex;
  align-items: center;
  gap: var(--dw-sp-2);
  padding: var(--dw-sp-2) var(--dw-sp-3);
  border: 0;
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
  background: transparent;
  color: var(--dw-text-muted);
  font-size: var(--dw-fs-base);
  font-weight: var(--dw-fw-semibold);
  cursor: pointer;
}
.sv-tab.is-active {
  color: var(--dw-primary);
  border-bottom-color: var(--dw-primary);
}
.sv-tab.is-active .dw-count {
  background: var(--dw-primary-soft);
  color: var(--dw-primary);
}
.sv-search {
  flex: 0 1 340px;
  min-width: 200px;
}
.sv-sort {
  flex: 0 0 180px;
}
.saved-table td:first-child {
  max-width: 0;
  width: 46%;
}
.sv-name {
  display: flex;
  align-items: center;
  gap: var(--dw-sp-3);
  width: 100%;
  border: 0;
  background: transparent;
  padding: 0;
  text-align: left;
  cursor: pointer;
  color: inherit;
  min-width: 0;
}
.sv-name__icon {
  width: 32px;
  height: 32px;
  border-radius: var(--dw-radius);
  background: var(--dw-primary-soft);
  color: var(--dw-primary);
  display: grid;
  place-items: center;
  flex-shrink: 0;
}
.sv-name__icon .v-icon {
  font-size: var(--dw-icon) !important;
}
.sv-name__text {
  display: flex;
  flex-direction: column;
  min-width: 0;
}
.sv-name__title,
.sv-name__desc {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.sv-name__title {
  font-weight: var(--dw-fw-semibold);
  color: var(--dw-text);
}
.sv-name:hover .sv-name__title {
  color: var(--dw-primary);
}
.sv-name__desc {
  font-size: var(--dw-fs-sm);
  color: var(--dw-text-muted);
}
.sv-name__spin {
  color: var(--dw-primary);
  margin-left: auto;
  flex-shrink: 0;
}
.col-actions {
  width: 52px;
  text-align: right;
}
.sv-owner {
  white-space: nowrap;
}
.sv-menu__danger {
  color: var(--dw-error);
}
.is-spinning {
  animation: dw-spin 0.8s linear infinite;
}
@media (max-width: 760px) {
  .col-owner,
  .col-modified {
    display: none;
  }
  .saved-table td:first-child {
    width: auto;
  }
}
</style>
