// Serialisation of a dashboard definition to/from the JSON file stored in the
// dashboard Document (requirements §6). Pure functions — no API or UI code here.
//
// The file never contains credentials, tokens, sharing recipients or data rows:
// only what is needed to rebuild the dashboard.

import { ApiError, ERROR_CODES } from "@/services/apiError";

export const DASHBOARD_KIND = "bwc.dashboard-widget.dashboard";
export const SCHEMA_VERSION = 1;

const isObj = (v) => v !== null && typeof v === "object" && !Array.isArray(v);
const arr = (v) => (Array.isArray(v) ? v : []);
const str = (v, max = 500) => (typeof v === "string" ? v.slice(0, max) : "");

// Fields of the custom query form (CustomFormView / dashboardApi.applyForm).
const FORM_KEYS = [
  "keyword", "status", "policy", "owner", "lastModifiedBy", "originator", "project",
  "createdFrom", "createdTo", "modifiedFrom", "modifiedTo",
];

function cleanForm(form) {
  if (!isObj(form)) return null;
  const out = {};
  FORM_KEYS.forEach((k) => {
    if (typeof form[k] === "string" && form[k]) out[k] = form[k].slice(0, 500);
  });
  if (Array.isArray(form.projectIds)) out.projectIds = form.projectIds.filter((v) => typeof v === "string").slice(0, 2000);
  if (Array.isArray(form.projectNames)) out.projectNames = form.projectNames.filter((v) => typeof v === "string").slice(0, 2000);
  return Object.keys(out).length ? out : null;
}

function cleanRefines(list) {
  return arr(list)
    .filter((r) => isObj(r) && typeof r.key === "string")
    .map((r) => ({
      key: r.key,
      value: r.value,
      ...(r.valueTo !== undefined && { valueTo: r.valueTo }),
      ...(r.label !== undefined && { label: str(r.label) }),
    }));
}

function cleanCharts(charts) {
  if (!isObj(charts)) return {};
  const out = {};
  Object.values(charts).forEach((c) => {
    if (!isObj(c) || typeof c.id !== "string") return;
    // Only the configuration is stored; data series are rebuilt on load.
    out[c.id] = { id: c.id, kind: str(c.kind, 40), title: str(c.title, 200), xAttr: str(c.xAttr, 200) };
  });
  return out;
}

function cleanViewSettings(v) {
  if (!isObj(v)) return null;
  const out = {};
  ["columns"].forEach((k) => Number.isInteger(v[k]) && (out[k] = v[k]));
  ["showKpis", "showFilterBar", "compact"].forEach((k) => typeof v[k] === "boolean" && (out[k] = v[k]));
  return out;
}

/**
 * Build the stored definition from the live dashboard state.
 * state: { type, source, customForm, chips, facetRefines, order, customCharts, viewSettings }
 */
export function buildDefinition(state) {
  if (!state || !state.type) throw new ApiError(ERROR_CODES.INVALID, { message: "Select an object type before saving." });
  return {
    kind: DASHBOARD_KIND,
    schemaVersion: SCHEMA_VERSION,
    objectType: str(state.type, 200),
    source: state.source === "external" ? "external" : "3dx",
    query: cleanForm(state.customForm),
    filters: {
      chips: arr(state.chips).filter((c) => typeof c === "string"),
      facetRefines: cleanRefines(state.facetRefines),
    },
    layout: {
      order: arr(state.order).filter((id) => typeof id === "string"),
      viewSettings: cleanViewSettings(state.viewSettings),
    },
    charts: cleanCharts(state.customCharts),
  };
}

export function serialize(state) {
  return JSON.stringify(buildDefinition(state), null, 2);
}

// Older definitions (the pre-document "saved view" objects) → v1.
function migrate(raw) {
  if (raw.kind === DASHBOARD_KIND) return raw;
  if (raw.type && (raw.order || raw.customCharts || raw.facetRefines || raw.chips)) {
    return {
      kind: DASHBOARD_KIND,
      schemaVersion: 1,
      objectType: raw.type,
      source: raw.source || "3dx",
      query: raw.customForm || null,
      filters: { chips: raw.chips, facetRefines: raw.facetRefines },
      layout: { order: raw.order, viewSettings: raw.viewSettings || null },
      charts: raw.customCharts,
    };
  }
  throw new ApiError(ERROR_CODES.MALFORMED, { message: "This document doesn't contain a dashboard definition." });
}

/**
 * Parse file content (string or object) into the restore state used by DashboardView.
 * Throws ApiError MALFORMED / UNSUPPORTED_VERSION.
 */
export function parse(content) {
  let raw = content;
  if (typeof content === "string") {
    try {
      raw = JSON.parse(content);
    } catch (e) {
      throw new ApiError(ERROR_CODES.MALFORMED);
    }
  }
  if (!isObj(raw)) throw new ApiError(ERROR_CODES.MALFORMED);
  const def = migrate(raw);
  const version = Number(def.schemaVersion);
  if (!Number.isInteger(version) || version < 1) throw new ApiError(ERROR_CODES.MALFORMED);
  if (version > SCHEMA_VERSION) throw new ApiError(ERROR_CODES.UNSUPPORTED_VERSION);
  if (typeof def.objectType !== "string" || !def.objectType) throw new ApiError(ERROR_CODES.MALFORMED);

  const filters = isObj(def.filters) ? def.filters : {};
  const layout = isObj(def.layout) ? def.layout : {};
  return {
    type: def.objectType,
    source: def.source === "external" ? "external" : "3dx",
    customForm: cleanForm(def.query),
    chips: arr(filters.chips).filter((c) => typeof c === "string"),
    facetRefines: cleanRefines(filters.facetRefines),
    order: arr(layout.order).filter((id) => typeof id === "string"),
    viewSettings: cleanViewSettings(layout.viewSettings),
    customCharts: cleanCharts(def.charts),
  };
}
