// Normalised API error: a user-safe message plus a machine-readable code.
// Raw server responses are never put in `message` (they can contain internal details);
// they are kept in `detail` for diagnostics only.

export const ERROR_CODES = {
  NETWORK: "NETWORK",
  UNAUTHENTICATED: "UNAUTHENTICATED",
  FORBIDDEN: "FORBIDDEN",
  NOT_FOUND: "NOT_FOUND",
  CONFLICT: "CONFLICT",
  INVALID: "INVALID",
  SERVER: "SERVER",
  NOT_CONFIGURED: "NOT_CONFIGURED",
  MALFORMED: "MALFORMED",
  UNSUPPORTED_VERSION: "UNSUPPORTED_VERSION",
};

const MESSAGES = {
  NETWORK: "The server could not be reached. Check your connection and try again.",
  UNAUTHENTICATED: "Your 3DEXPERIENCE session has expired. Reload the widget to sign in again.",
  FORBIDDEN: "You don't have permission to do this.",
  NOT_FOUND: "The item no longer exists or you no longer have access to it.",
  CONFLICT: "Someone else changed this item. Reload it and try again.",
  INVALID: "The request was rejected. Check the values and try again.",
  SERVER: "The server reported an error. Try again in a moment.",
  NOT_CONFIGURED: "This feature isn't configured for this platform.",
  MALFORMED: "The saved content is damaged and can't be opened.",
  UNSUPPORTED_VERSION: "This dashboard was saved by a newer version of the widget.",
};

export class ApiError extends Error {
  constructor(code, { status = 0, message, detail } = {}) {
    super(message || MESSAGES[code] || MESSAGES.SERVER);
    this.name = "ApiError";
    this.code = code;
    this.status = status;
    this.detail = detail;
  }
}

export function codeForStatus(status) {
  if (status === 401) return ERROR_CODES.UNAUTHENTICATED;
  if (status === 403) return ERROR_CODES.FORBIDDEN;
  if (status === 404) return ERROR_CODES.NOT_FOUND;
  if (status === 409 || status === 412) return ERROR_CODES.CONFLICT;
  if (status >= 400 && status < 500) return ERROR_CODES.INVALID;
  return ERROR_CODES.SERVER;
}

// Message to show in the UI for any thrown value.
export function userMessage(err, fallback = MESSAGES.SERVER) {
  if (err instanceof ApiError) return err.message;
  return fallback;
}
