<template>
  <v-app>
    <v-navigation-drawer permanent rail class="app-rail" v-if="!['type', 'form', 'activity'].includes(screen) && !store.startupError">
      <v-list nav density="compact" aria-label="Widget sections">
        <v-tooltip v-for="item in navList" :key="item.id" :text="item.label" location="end">
          <template #activator="{ props }">
            <v-list-item
              v-bind="props"
              :prepend-icon="item.icon"
              :title="item.label"
              :aria-label="item.label"
              color="primary"
              :active="screen === item.id"
              @click="screen = item.id"
            />
          </template>
        </v-tooltip>
      </v-list>
    </v-navigation-drawer>

    <v-main class="app-main">
      <div class="app-content">
        <StateMessage
          v-if="store.startupError"
          tone="error"
          icon="mdi-power-plug-off-outline"
          :title="errorText.widgetStartTitle"
          :message="store.startupError"
          action-label="Reload widget"
          @action="reload"
        />
        <template v-else>
          <TypeSelectionView
            v-if="screen === 'type'"
            @open-form="screen = 'form'"
            @open-activity="screen = 'activity'"
            @open-dashboard="onOpenDashboard"
            @open-saved-dashboard="onOpenSavedDashboard"
            @open-saved-list="screen = 'saved'"
          />
          <MyActivityView v-else-if="screen === 'activity'" @go-home="screen = 'type'" />
          <CustomFormView v-else-if="screen === 'form'" @open-dashboard="onOpenDashboard" @go-home="screen = 'type'" />
          <DashboardView
            v-else-if="screen === 'dashboard'"
            :key="dashboardKey"
            :restore-dashboard="pendingDashboard"
            @saved="onDashboardSaved"
            @go-home="screen = 'type'"
          />
          <ScheduleView v-else-if="screen === 'schedule'" />
          <SavedDashboardsView v-else-if="screen === 'saved'" @open="onOpenSavedDashboard" @new="screen = 'type'" />
        </template>
      </div>
    </v-main>
    <AppToast />
  </v-app>
</template>

<script>
import TypeSelectionView from "@/views/TypeSelectionView.vue";
import DashboardView from "@/views/DashboardView.vue";
import AppToast from "@/components/common/AppToast.vue";
import StateMessage from "@/components/common/StateMessage.vue";
import { useDashboardStore } from "@/store/dashboardStore";
import MyActivityView from "@/views/MyActivityView.vue";
import CustomFormView from "@/views/CustomFormView.vue";
import ScheduleView from "@/views/ScheduleView.vue";
import SavedDashboardsView from "@/views/SavedDashboardsView.vue";
import { ERROR_TEXT } from "@/utils/uiText";

export default {
  name: "App",
  setup() {
    return { store: useDashboardStore() };
  },
  components: {
    TypeSelectionView,
    DashboardView,
    AppToast,
    StateMessage,
    CustomFormView,
    ScheduleView,
    SavedDashboardsView,
    MyActivityView,
  },
  props: {
    widget: { type: Object, default: null },
  },
  data() {
    return {
      errorText: ERROR_TEXT,
      pendingDashboard: null,
      dashboardKey: 0,
      screen: "type",
    };
  },
  mounted() {
    // External-source credentials (FR-22) stay in the widget's own preferences and are
    // never written to dashboard documents.
    const w = window.widget;
    w?.addPreference?.({ name: "extEmail", type: "text", label: "External email", defaultValue: "" });
    w?.addPreference?.({ name: "extPassword", type: "password", label: "External password", defaultValue: "" });
  },
  watch: {
    screen(newScreen) {
      if (newScreen === "type") {
        // FR-04: transient custom-query state is cleared when going Home.
        this.store.setCustomForm(null);
        this.store.setSource("3dx");
        this.widget?.setTitle("Attribute Driven Dashboard Widget");
      }
    },
  },
  computed: {
    navList() {
      const items = [
        { id: "type", icon: "mdi-home-outline", label: "Home" },
        { id: "dashboard", icon: "mdi-chart-line", label: "Dashboard" },
        { id: "schedule", icon: "mdi-calendar-clock-outline", label: "Project schedule" },
        { id: "saved", icon: "mdi-bookmark-outline", label: "Saved dashboards" },
      ];
      // Project Schedule is offered for 3DEXPERIENCE projects, as before.
      return items.filter(
        (i) => i.id !== "schedule" || (this.store.type === "Project" && this.store.source !== "external"),
      );
    },
  },
  methods: {
    go(id) {
      this.screen = id;
    },
    reload() {
      window.location.reload();
    },
    // view = { meta, state } from dashboardDocumentApi.open
    onOpenSavedDashboard(view) {
      this.widget?.setTitle(view?.meta?.name || "Dashboard");
      this.pendingDashboard = view;
      this.dashboardKey++;
      this.screen = "dashboard";
    },
    onOpenDashboard() {
      this.widget?.setTitle(this.store.type || "Dashboard");
      this.pendingDashboard = null;
      this.dashboardKey++;
      this.screen = "dashboard";
    },
    onDashboardSaved(view) {
      // Keep the saved document attached when navigating away and back.
      this.pendingDashboard = view;
      this.widget?.setTitle(view?.meta?.name || "Dashboard");
    },
  },
};
</script>

<style lang="scss">
@use "@/assets/styles/dashboard.scss";
</style>

<style scoped>
.app-main {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  background: var(--dw-bg);
}

.app-content {
  flex: 1;
  min-width: 0;
}

.app-rail {
  background: var(--dw-surface) !important;
  border-right: 1px solid var(--dw-border) !important;
}

.app-rail :deep(.v-list-item) {
  border-radius: var(--dw-radius);
  margin-bottom: 2px;
  color: var(--dw-text-muted);
}

.app-rail :deep(.v-list-item--active) {
  color: var(--dw-primary);
  background: var(--dw-primary-soft);
}

.app-rail :deep(.v-list-item--active > .v-list-item__overlay) {
  opacity: 0;
}
</style>
