<template>
  <div class="ts-flip-stage" :class="{ flipping: isFlipping }">
    <div class="ts-wrap">
      <div class="ts-panel">
        <div class="ts-header-row">
          <div class="ts-header-left">
            <button v-if="mode === 'type'" type="button" class="ts-flip" @click="$emit('open-form')">
              <v-icon icon="mdi-form-select" size="16" />
              Custom Query
            </button>
          </div>

          <div class="ts-header-center">
            <h2 class="ts-title">
              {{ mode === "type" ? "New Dashboard" : "My Saved Dashboards test" }}
            </h2>
            <div class="ts-subtitle">
              {{ mode === "type" ? "Choose a type to start a new dashboard" : "Pick a dashboard you saved before" }}
            </div>
          </div>

          <div class="ts-header-right">
            <button
              type="button"
              class="ts-flip"
              :class="{ flipping: isFlipping }"
              :title="mode === 'type' ? 'Show saved dashboards' : 'Show object types'"
              @click="flipMode"
            >
              <v-icon class="ts-flip-icon" :icon="mode === 'type' ? 'mdi-content-save-outline' : 'mdi-view-grid-outline'" size="16" />
              {{ mode === "type" ? "Saved Dashboards" : "Object Types" }}
            </button>
          </div>
        </div>

        <div class="ts-search">
          <v-text-field
            v-model="search"
            prepend-inner-icon="mdi-magnify"
            :placeholder="mode === 'type' ? text.searchPlaceholder : 'Search dashboards...'"
            :aria-label="mode === 'type' ? 'Search object types' : 'Search dashboards'"
            density="comfortable"
            hide-details
            clearable
            style="max-width: 360px; width: 100%"
          />
        </div>

        <!-- Object types -->
        <div v-if="mode === 'type'" class="ts-card-container">
          <div class="ts-grid-featured">
            <button
              v-for="type in filteredTypes.slice(0, 8)"
              :key="type.name"
              type="button"
              class="ts-card featured"
              :class="{ 'is-active': selected === type.name }"
              @click="selectType(type.name)"
            >
              <span class="ts-badge"><v-icon :icon="type.icon" size="20" /></span>
              <span class="ts-card-label">{{ type.name }}</span>
            </button>
          </div>

          <div v-if="filteredTypes.length > 8" class="ts-grid-compact">
            <button
              v-for="type in filteredTypes.slice(8)"
              :key="'small-' + type.name"
              type="button"
              class="ts-card compact"
              :class="{ 'is-active': selected === type.name }"
              @click="selectType(type.name)"
            >
              <span class="ts-badge"><v-icon :icon="type.icon" size="16" /></span>
              <span class="ts-card-label">{{ type.name }}</span>
            </button>
          </div>
          <div v-if="!filteredTypes.length" class="ts-empty">No object types match “{{ search }}”.</div>
        </div>

        <!-- Saved dashboards (3DEXPERIENCE Documents the user owns or that are shared with them) -->
        <div v-else class="ts-card-container">
          <div class="ts-grid-featured">
            <button type="button" class="ts-card featured" @click="$emit('open-activity')">
              <span class="ts-badge"><v-icon icon="mdi-account-clock-outline" size="20" /></span>
              <span class="ts-system-badge">Default</span>
              <span class="ts-card-label">My Activity</span>
            </button>
            <button type="button" class="ts-card featured" @click="showDefault = true">
              <span class="ts-badge"><v-icon icon="mdi-star-circle-outline" size="20" /></span>
              <span class="ts-system-badge">Default</span>
              <span class="ts-card-label">Projects Monitoring</span>
            </button>

            <template v-if="loadingSaved">
              <div v-for="n in 2" :key="'sk' + n" class="ts-card featured ts-card--skeleton" aria-hidden="true">
                <span class="dw-skeleton" style="width: 40px; height: 40px; border-radius: 50%" />
                <span class="dw-skeleton" style="width: 70%; height: 10px" />
              </div>
            </template>
            <button
              v-for="v in filteredSavedDashboards.slice(0, 6)"
              v-else
              :key="v.id"
              type="button"
              class="ts-card featured"
              :class="{ 'is-active': opening === v.id }"
              :disabled="!!opening"
              :title="v.access === 'owner' ? v.name : `${v.name} — shared by ${v.ownerName || v.owner}`"
              @click="selectSavedView(v)"
            >
              <span class="ts-badge">
                <span v-if="opening === v.id" class="dw-spinner" aria-label="Opening" />
                <v-icon v-else icon="mdi-view-dashboard-outline" size="20" />
              </span>
              <span v-if="v.access !== 'owner'" class="ts-system-badge ts-system-badge--shared">Shared</span>
              <span class="ts-card-label">{{ v.name }}</span>
            </button>
          </div>

          <div v-if="!loadingSaved && filteredSavedDashboards.length > 6" class="ts-grid-compact">
            <button
              v-for="v in filteredSavedDashboards.slice(6)"
              :key="'small-' + v.id"
              type="button"
              class="ts-card compact"
              :class="{ 'is-active': opening === v.id }"
              :disabled="!!opening"
              :title="v.name"
              @click="selectSavedView(v)"
            >
              <span class="ts-badge"><v-icon icon="mdi-view-dashboard-outline" size="16" /></span>
              <span v-if="v.access !== 'owner'" class="ts-system-badge ts-system-badge--shared">Shared</span>
              <span class="ts-card-label">{{ v.name }}</span>
            </button>
          </div>

          <div v-if="savedError" class="dw-alert dw-alert--error ts-alert" role="alert">
            <v-icon icon="mdi-alert-circle-outline" size="18" />
            <span>{{ savedError }}</span>
            <span class="dw-spacer" />
            <button type="button" class="btn-ghost btn-sm" @click="loadSavedDashboards">Try again</button>
          </div>
          <div v-else-if="!loadingSaved && !filteredSavedDashboards.length" class="ts-empty">
            {{ search ? `No saved dashboards match “${search}”.` : "No saved dashboards yet. Open a dashboard and use Save Dashboard to keep it here." }}
          </div>
        </div>
      </div>
    </div>

    <DefaultDashboardDialog v-model="showDefault" :loading="busy" @submit="openDefault" />
    <SourceChoiceDialog v-model="showSource" @pick="onPickSource" />
  </div>
</template>

<script>
import { ERROR_TEXT, TYPE_SELECTION_TEXT } from "@/utils/uiText";
import { useDashboardStore } from "@/store/dashboardStore";
import dashboardDocumentApi from "@/services/dashboardDocumentApi";
import dashboardApi from "@/services/dashboardApi";
import { userMessage } from "@/services/apiError";
import { toastBus } from "@/components/common/toastBus";
import DefaultDashboardDialog from "@/components/dashboard/DefaultDashboardDialog.vue";
import SourceChoiceDialog from "@/components/SourceChoiceDialog.vue";

export default {
  name: "TypeSelectionView",

  components: { DefaultDashboardDialog, SourceChoiceDialog },

  emits: ["open-dashboard", "open-saved-dashboard", "open-form", "open-activity", "open-saved-list"],

  setup() {
    return { store: useDashboardStore() };
  },

  data() {
    return {
      mode: "saved",
      isFlipping: false,
      savedDashboards: [],
      loadingSaved: false,
      savedError: "",
      opening: null,
      text: TYPE_SELECTION_TEXT,
      search: "",
      selected: this.store.type,
      showDefault: false,
      busy: false,
      showSource: false,
    };
  },

  computed: {
    types() {
      return this.store.getTypeOptions;
    },
    filteredTypes() {
      const q = (this.search || "").trim().toLowerCase();
      if (!q) return this.types;
      return this.types.filter((t) => t.name.toLowerCase().includes(q));
    },
    filteredSavedDashboards() {
      const q = (this.search || "").trim().toLowerCase();
      if (!q) return this.savedDashboards;
      return this.savedDashboards.filter((view) => view.name.toLowerCase().includes(q));
    },
  },

  async mounted() {
    if (this.mode === "saved") await this.loadSavedDashboards();
  },
  beforeUnmount() {
    this.showSource = false;
    this.showDefault = false;
  },
  methods: {
    // Dashboard documents the platform returns as accessible (owned + shared with me).
    async loadSavedDashboards() {
      this.loadingSaved = true;
      this.savedError = "";
      try {
        this.savedDashboards = await dashboardDocumentApi.list();
      } catch (e) {
        this.savedError = userMessage(e, ERROR_TEXT.loadSavedDashboards);
      } finally {
        this.loadingSaved = false;
      }
    },
    selectType(name) {
      this.selected = name;
      if (name === "Project") {
        this.showSource = true; // ask 3DEXPERIENCE or External
        return;
      }
      this.store.setSource("3dx");
      this.openDashboard();
    },
    onPickSource(source) {
      this.store.setSource(source);
      this.showSource = false;
      setTimeout(() => this.openDashboard(), 300);
    },
    async selectSavedView(v) {
      if (this.opening) return;
      this.opening = v.id;
      try {
        this.$emit("open-saved-dashboard", await dashboardDocumentApi.open(v.id));
      } catch (e) {
        toastBus.emit(userMessage(e, ERROR_TEXT.openDashboard), "error");
        this.loadSavedDashboards(); // access may have been revoked
      } finally {
        this.opening = null;
      }
    },
    async flipMode() {
      this.isFlipping = true;
      setTimeout(() => {
        this.isFlipping = false;
      }, 500);
      this.mode = this.mode === "type" ? "saved" : "type";
      this.search = "";
      if (this.mode === "saved" && !this.savedDashboards.length && !this.loadingSaved) {
        await this.loadSavedDashboards();
      }
    },
    openDashboard() {
      this.store.setType(this.selected);
      this.$emit("open-dashboard", {});
    },
    async openDefault(form) {
      this.busy = true;
      try {
        this.store.setCustomForm(null); // old form must not affect the sub object search
        const { names, ids } = await dashboardApi.fetchProjectNamesBySubObject(form);
        if (!names.length && !ids.length) {
          return toastBus.emit(ERROR_TEXT.noMatchingProjects, "warning");
        }
        this.store.setType("Project");
        this.store.setCustomForm({ projectNames: names, projectIds: ids });
        this.showDefault = false;
        setTimeout(() => this.$emit("open-dashboard", {}), 300);
      } catch (e) {
        toastBus.emit(ERROR_TEXT.loadProjects, "error");
      } finally {
        this.busy = false;
      }
    },
  },
};
</script>

<style scoped>
.ts-wrap {
  min-height: calc(100vh - 20px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--dw-sp-4);
  box-sizing: border-box;
}

.ts-panel {
  width: 100%;
  max-width: 760px;
  height: 90vh;
  background: var(--dw-surface);
  border: 1px solid var(--dw-border);
  border-radius: var(--dw-radius-lg);
  box-shadow: var(--dw-shadow-sm);
  padding: 28px 32px;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
}

.ts-search {
  flex: 0 0 auto;
  display: flex;
  justify-content: center;
  margin-bottom: 20px;
}

.ts-header-row {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: var(--dw-sp-3);
  margin-bottom: 24px;
}

.ts-header-left {
  display: flex;
  justify-content: flex-start;
  align-items: center;
}

.ts-header-center {
  text-align: center;
}

.ts-header-right {
  display: flex;
  justify-content: flex-end;
  align-items: center;
}

.ts-flip {
  display: flex;
  align-items: center;
  gap: 6px;
  height: var(--dw-control-h-sm);
  border: 1px solid var(--dw-border-strong);
  border-radius: var(--dw-radius);
  padding: 0 var(--dw-sp-3);
  font-family: inherit;
  font-size: var(--dw-fs-sm);
  font-weight: var(--dw-fw-medium);
  color: var(--dw-text-2);
  background: var(--dw-surface);
  cursor: pointer;
  white-space: nowrap;
  transition: background var(--dw-transition), border-color var(--dw-transition), color var(--dw-transition);
}

.ts-flip:hover {
  border-color: var(--dw-primary);
  color: var(--dw-primary);
  background: var(--dw-primary-soft);
}

.ts-flip-icon {
  transition: transform 0.35s ease;
}

.ts-flip.flipping .ts-flip-icon {
  transform: rotateY(180deg);
}

.ts-flip-stage {
  perspective: 1200px;
}

.ts-flip-stage.flipping {
  animation: ts-page-flip 0.5s ease;
  transform-style: preserve-3d;
}

@keyframes ts-page-flip {
  0% {
    transform: rotateY(0deg);
    opacity: 1;
  }
  50% {
    transform: rotateY(90deg);
    opacity: 0.3;
  }
  100% {
    transform: rotateY(0deg);
    opacity: 1;
  }
}

@media (prefers-reduced-motion: reduce) {
  .ts-flip-stage.flipping {
    animation: none;
  }
}

.ts-empty {
  text-align: center;
  color: var(--dw-text-muted);
  font-size: var(--dw-fs-base);
  padding: 20px;
}

.ts-alert {
  margin-top: var(--dw-sp-2);
  align-items: center;
}

.ts-title {
  font-size: var(--dw-fs-xl);
  font-weight: var(--dw-fw-semibold);
  margin: 0 0 4px;
  color: var(--dw-text);
}

.ts-subtitle {
  font-size: var(--dw-fs-base);
  color: var(--dw-text-muted);
}

.ts-grid-featured {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
  margin-bottom: 18px;
}

.ts-grid-compact {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 10px;
}

.ts-card {
  position: relative;
  border: 1px solid var(--dw-border);
  background: var(--dw-surface);
  border-radius: var(--dw-radius-lg);
  padding: 18px 6px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  cursor: pointer;
  box-sizing: border-box;
  font-family: inherit;
  color: var(--dw-text-2);
  min-width: 0;
  transition: border-color var(--dw-transition), box-shadow var(--dw-transition), background var(--dw-transition);
}

.ts-card:hover:not(:disabled) {
  border-color: var(--dw-accent);
  box-shadow: var(--dw-shadow-sm);
}

.ts-card:disabled {
  cursor: progress;
}

.ts-card.is-active {
  border: 1.5px solid var(--dw-primary);
  background: var(--dw-primary-soft);
}

.ts-card--skeleton {
  cursor: default;
}

.ts-card.featured {
  min-height: 110px;
}

.ts-card.compact {
  min-height: 75px;
  padding: 10px 4px;
}

.ts-card.compact .ts-badge {
  width: 28px;
  height: 28px;
}

.ts-card.compact .ts-card-label {
  font-size: var(--dw-fs-xs);
}

.ts-system-badge {
  position: absolute;
  top: 6px;
  right: 6px;
  font-size: var(--dw-fs-xs);
  font-weight: var(--dw-fw-semibold);
  color: var(--dw-primary);
  background: var(--dw-primary-soft);
  border-radius: var(--dw-radius-sm);
  padding: 1px 6px;
}

.ts-system-badge--shared {
  color: var(--dw-text-2);
  background: var(--dw-surface-muted);
}

.ts-badge {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--dw-surface-muted);
  color: var(--dw-text-2);
  transition: background var(--dw-transition), color var(--dw-transition);
}

.ts-card:hover:not(:disabled) .ts-badge {
  background: var(--dw-accent-soft);
  color: var(--dw-primary);
}

.ts-card.is-active .ts-badge {
  background: var(--dw-primary);
  color: var(--dw-on-primary);
}

.ts-card-label {
  font-size: var(--dw-fs-base);
  font-weight: var(--dw-fw-medium);
  text-align: center;
  max-width: 100%;
  padding: 0 4px;
  overflow: hidden;
  text-overflow: ellipsis;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

.ts-card.is-active .ts-card-label {
  color: var(--dw-primary);
}

.ts-card-container {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 2px 6px 2px 2px;
}

@media (max-width: 600px) {
  .ts-grid-featured {
    grid-template-columns: repeat(2, 1fr);
  }
  .ts-grid-compact {
    grid-template-columns: repeat(3, 1fr);
  }
  .ts-wrap {
    padding: var(--dw-sp-3);
  }
  .ts-panel {
    padding: 20px 16px;
    height: auto;
    min-height: 90vh;
  }
  .ts-header-row {
    grid-template-columns: 1fr;
    justify-items: center;
  }
}
</style>
