<template>
  <DwDialog
    :model-value="modelValue"
    :title="text.title"
    subtitle="Layout settings are saved with the dashboard."
    icon="mdi-view-dashboard-edit-outline"
    max-width="460"
    @update:model-value="$emit('update:modelValue', $event)"
  >
    <fieldset class="vs-fieldset">
      <legend class="dw-label">{{ text.layoutLabel }}</legend>
      <div class="cols-grid" role="radiogroup" :aria-label="text.layoutLabel">
        <button
          v-for="n in columnChoices"
          :key="n"
          type="button"
          role="radio"
          class="cols-card"
          :class="{ active: form.columns === n }"
          :aria-checked="form.columns === n ? 'true' : 'false'"
          @click="form.columns = n"
        >
          <span class="cols-preview" aria-hidden="true"><span v-for="i in n" :key="i" /></span>
          <span>{{ n }} columns</span>
        </button>
      </div>
    </fieldset>

    <div class="vs-toggles">
      <v-switch v-model="form.showKpis" :label="text.showKpis" hide-details />
      <v-switch v-model="form.showFilterBar" :label="text.showFilterBar" hide-details />
      <v-switch v-model="form.compact" :label="text.compactMode" hide-details />
    </div>

    <template #footer>
      <button type="button" class="btn-ghost" @click="reset">{{ text.reset }}</button>
      <span class="dw-spacer" />
      <button type="button" class="btn-outline" @click="close">Cancel</button>
      <button type="button" class="btn-primary" @click="apply">{{ text.apply }}</button>
    </template>
  </DwDialog>
</template>

<script>
import DwDialog from "@/components/common/DwDialog.vue";
import { DEFAULT_VIEW_SETTINGS, LAYOUT_COLUMN_CHOICES } from "@/utils/dashboardData";
import { VIEW_SETTINGS_TEXT } from "@/utils/uiText";

export default {
  name: "ViewSettingsDialog",
  components: { DwDialog },
  props: {
    modelValue: { type: Boolean, default: false },
    settings: { type: Object, default: () => ({ ...DEFAULT_VIEW_SETTINGS }) },
  },
  emits: ["update:modelValue", "apply"],

  data() {
    return {
      text: VIEW_SETTINGS_TEXT,
      columnChoices: LAYOUT_COLUMN_CHOICES,
      form: { ...DEFAULT_VIEW_SETTINGS, ...this.settings },
    };
  },

  watch: {
    modelValue(v) {
      if (v) this.form = { ...DEFAULT_VIEW_SETTINGS, ...this.settings };
    },
  },

  methods: {
    close() {
      this.$emit("update:modelValue", false);
    },
    reset() {
      this.form = { ...DEFAULT_VIEW_SETTINGS };
    },
    apply() {
      this.$emit("apply", { ...this.form });
      this.close();
    },
  },
};
</script>

<style scoped>
.vs-fieldset {
  border: 0;
  padding: 0;
  margin: 0;
}
.vs-fieldset legend {
  margin-bottom: var(--dw-sp-2);
}
.cols-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--dw-sp-2);
}
.cols-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--dw-sp-2);
  padding: var(--dw-sp-3) var(--dw-sp-2);
  border: 1px solid var(--dw-border);
  border-radius: var(--dw-radius);
  background: var(--dw-surface);
  color: var(--dw-text-2);
  font-family: inherit;
  font-size: var(--dw-fs-sm);
  cursor: pointer;
}
.cols-card.active {
  border-color: var(--dw-primary);
  background: var(--dw-primary-soft);
  color: var(--dw-primary);
  font-weight: var(--dw-fw-semibold);
}
.cols-preview {
  display: flex;
  gap: 3px;
  width: 100%;
  max-width: 64px;
  height: 22px;
}
.cols-preview span {
  flex: 1;
  border-radius: 3px;
  background: var(--dw-border-strong);
}
.cols-card.active .cols-preview span {
  background: var(--dw-primary);
  opacity: 0.6;
}
.vs-toggles {
  display: flex;
  flex-direction: column;
}
</style>
